import appLogger from '@/utils/logger/app-logger';

class Configuration {
  public getClientId(): string {
    const clientId = import.meta.env.IDENTITY_PROVIDER_APP_CLIENT_ID;
    if (!clientId) {
      throw new Error('CLIENT_ID not found in environment variables.');
    }
    return clientId;
  }

  public getRedirectUri(): string {
    const redirectUri = import.meta.env.APP_REDIRECT_URI;
    if (!redirectUri) {
      throw new Error('REDIRECT_URI not found in environment variables.');
    }
    appLogger.debug(this);
    return redirectUri;
  }

  public getAuthority(): string {
    const authority = import.meta.env.IDENTITY_PROVIDER_APP_AUTHORITY;
    if (!authority) {
      throw new Error('AUTHORITY not found in environment variables.');
    }
    appLogger.debug(this);
    return authority;
  }

  public getScopes(): string {
    const scopes = import.meta.env.IDENTITY_PROVIDER_APP_SCOPES;
    if (!scopes) {
      throw new Error('SCOPES not found in environment variables.');
    }
    appLogger.debug(this);
    return scopes;
  }

  public getResponseType(): string {
    appLogger.debug(this);
    const code = import.meta.env.IDENTITY_PROVIDER_APP_RESPONSE_TYPE;
    return code;
  }

  public getAccessTokenExpiringNotificationTime(): number {
    appLogger.debug(this);
    const value =
      import.meta.env.ACCESS_TOKEN_EXPIRING_REFRESH_SECONDS || '1800';
    return Number.parseInt(value, 10);
  }
}

const configuration = new Configuration();

export { configuration };

import { AuthConfigService } from '@mesx/common-ui-lib';
import { WebStorageStateStore } from 'oidc-client';
import type { Router } from 'vue-router';
import { configuration } from './configuration';
import { AuthConfigDTO } from '@/types/auth.config.dto';

// Keep track of auth services per app
const authServices = new Map<string, AuthConfigService>();

// Shared storage keys across all apps
const SHARED_USER_ID_KEY = 'userId';
const SHARED_USER_ATTRIBUTES_KEY = 'userAttributes';

/**
 * Gets or creates an authentication service for a specific application
 * Each app uses shared OIDC state storage to enable simultaneous authentication across tabs
 * @param appName The name of the application to get the auth service for
 * @returns The AuthConfigService instance for the specified application
 */
export function getAuthService(appName: string): AuthConfigService {
  const normalizedAppName = appName.toLowerCase();

  if (!authServices.has(normalizedAppName)) {
    // Create app-specific auth config with SHARED storage for cross-app state synchronization
    // Using sessionStorage without app-specific prefix allows state sharing across tabs
    const appConfig = new AuthConfigDTO(
      configuration.getAuthority(),
      configuration.getClientId(),
      configuration.getRedirectUri(),
      configuration.getResponseType(),
      configuration.getScopes(),
      new WebStorageStateStore({
        store: globalThis.sessionStorage,
        prefix: 'oidc.', // Shared prefix across all apps for cross-tab synchronization
      }),
      configuration.getAccessTokenExpiringNotificationTime(),
    );

    // Create and store new auth service with app-specific config
    const authService = new AuthConfigService(appConfig);
    authServices.set(normalizedAppName, authService);
  }

  const authService = authServices.get(normalizedAppName);
  if (!authService) {
    throw new Error(`Auth service not found for app: ${appName}`);
  }
  return authService;
}

// Initialize auth for a specific app
/**
 *
 * @param appName The name of the application to initialize authentication for
 * @param router The Vue Router instance used for navigation during authentication
 */
export async function initializeAppAuth(
  appName: string,
  router: Router,
): Promise<void> {
  const authService = getAuthService(appName);
  await authService.initializeAuthentication(router);
}

// Clean up auth for a specific app
/**
 * Logout the specified app. Note: Shared userId and userAttributes are NOT removed
 * to allow seamless transitions between tabs and apps. They are only cleared on
 * complete session termination or user-initiated clear.
 * @param appName The name of the application to clean up authentication for
 */
export async function logoutApp(appName: string): Promise<void> {
  const normalizedAppName = appName.toLowerCase();
  const authService = authServices.get(normalizedAppName);
  if (authService) {
    await authService.logout();
    authServices.delete(normalizedAppName);
    // Do NOT remove userId and userAttributes - they are shared across apps
    // This allows users to stay authenticated when switching between app tabs
  }
}

/**
 * Get the shared userId stored in localStorage (used by all apps)
 * @returns The userId or undefined if not set
 */
export function getSharedUserId(): string | null {
  return localStorage.getItem(SHARED_USER_ID_KEY);
}

/**
 * Set the shared userId in localStorage (used by all apps)
 * @param userId The user ID to store
 */
export function setSharedUserId(userId: string): void {
  localStorage.setItem(SHARED_USER_ID_KEY, userId);
}

/**
 * Get the shared user attributes stored in localStorage (used by all apps)
 * @returns The user attributes object or null if not set
 */
export function getSharedUserAttributes(): Record<string, string> | undefined {
  const stored = localStorage.getItem(SHARED_USER_ATTRIBUTES_KEY);
  return stored ? JSON.parse(stored) : undefined;
}

/**
 * Set the shared user attributes in localStorage (used by all apps)
 * @param attributes The user attributes to store
 */
export function setSharedUserAttributes(
  attributes: Record<string, string>,
): void {
  localStorage.setItem(SHARED_USER_ATTRIBUTES_KEY, JSON.stringify(attributes));
}

/**
 * Clear all shared user data (userId and userAttributes)
 * Call this on complete logout or session termination
 */
export function clearSharedUserData(): void {
  localStorage.removeItem(SHARED_USER_ID_KEY);
  localStorage.removeItem(SHARED_USER_ATTRIBUTES_KEY);
}

import {
  ApiService,
  UserAttributesManager,
  authorizeUser,
} from '@mesx/common-ui-lib';
