const umeBaseUrl = import.meta.env.UME_API_URL;
const tokenEnvironment = import.meta.env.TOKEN;
const redirectUri = import.meta.env.APP_REDIRECT_URI;
let appBasePath: string;
if (redirectUri) {
  const parts = redirectUri.split('/');
  appBasePath = parts.pop() || '';
}

export const useProfileStore = defineStore('user', {
  actions: {
    async authenticateUser(appName?: string) {
      const useUser = useUserStore();
      const user = await this.getUser();
      if (!user) {
        appLogger.error('User not found');
        return;
      }

      const resolvedAppName = appName || this.getAppName();
      const apiService = new ApiService(
        umeBaseUrl,
        tokenEnvironment,
        resolvedAppName,
      );
      const fetchedUser = await apiService.getUserByEmail(user.profile.email);
      if (fetchedUser) {
        // Store shared userId in localStorage (used by all apps)
        setSharedUserId(fetchedUser.userId);
        await apiService.updateUserLastLoginByEmail(
          fetchedUser.email,
          new Date(),
        );
      } else {
        const userDetails = {
          firstName: user.profile.given_name,
          lastName: user.profile.family_name,
          email: user.profile.email,
          lastLogin: new Date(),
        };
        await apiService.saveUser(userDetails);
      }
      useUser.setProfile(
        `${user.profile.given_name} ${user.profile.family_name}`,
      );
    },

    async authorizeUser(appName?: string) {
      const router = useRouter();
      const user = await getUser();
      if (user) {
        const resolvedAppName = appName || this.getAppName();
        const apiService = new ApiService(
          umeBaseUrl,
          tokenEnvironment,
          resolvedAppName,
        );
        const roleNamesString = user.profile.groups.join(',');
        await authorizeUser(apiService, roleNamesString, router, appBasePath);
      }
    },

    async fetchUserAttributes(appName?: string) {
      try {
        const resolvedAppName = appName || this.getAppName();
        const apiService = new ApiService(
          umeBaseUrl,
          tokenEnvironment,
          resolvedAppName,
        );
        const userAttributesManager = new UserAttributesManager(apiService);
        const attributes = await userAttributesManager.loadAttributes();
        const userAttributes =
          userAttributesManager.transformAttributesToStorageFormat(attributes);
        if (userAttributes) {
          // Store shared user attributes in localStorage (used by all apps)
          setSharedUserAttributes(userAttributes);
          this.userAttributes = { ...userAttributes };
        } else {
          appLogger.warn('No user attributes found.');
        }
      } catch (error) {
        appLogger.error(`Error fetching user attributes: ${error}`);
      }
    },

    getAppName(routeOrPath?: RouteLocationNormalized | string): string {
      const router = useRouter();

      // If a route object was passed, check matched routes for appName
      if (routeOrPath && typeof routeOrPath !== 'string') {
        // Debug logging for troubleshooting
        appLogger.debug(
          JSON.stringify({
            message: '[getAppName] Route',
            path: routeOrPath.path,
            meta: routeOrPath.meta,
            matched: routeOrPath.matched.map((m) => ({
              path: m.path,
              meta: m.meta,
            })),
          }),
        );

        // First check the route's own meta
        if (routeOrPath.meta?.appName) {
          const appName = routeOrPath.meta.appName as string;
          appLogger.debug(`[getAppName] Using route meta.appName: ${appName}`);
          return appName;
        }

        // Then check matched routes from most specific to general
        for (const match of routeOrPath.matched) {
          if (match.meta?.appName) {
            const appName = match.meta.appName as string;
            appLogger.debug(
              `[getAppName] Using matched route meta.appName: ${appName}`,
            );
            // Console log removed for SonarQube compliance
            return appName;
          }
        }

        // Fallback to path-based detection for route object
        if (routeOrPath.path.includes('/edashboard')) {
          appLogger.debug(
            '[getAppName] Using path-based detection: EDASHBOARD-SCREEN',
          );
          return 'EDASHBOARD-SCREEN';
        }
        if (routeOrPath.path.includes('/live-status')) {
          appLogger.debug(
            '[getAppName] Using path-based detection: LIVE-STATUS-SCREEN',
          );
          return 'LIVE-STATUS-SCREEN';
        }
        if (routeOrPath.path.includes('/hry-transco')) {
          appLogger.debug(
            '[getAppName] Using path-based detection: HIERARCHY-TRANSCODIFICATION-SCREEN',
          );
          return 'HIERARCHY-TRANSCODIFICATION-SCREEN';
        }
      }

      // Handle string path or fallback to current route
      const { path: currentPath } = router.currentRoute.value;
      const path = typeof routeOrPath === 'string' ? routeOrPath : currentPath;

      if (path.includes('/edashboard')) return 'EDASHBOARD-SCREEN';
      if (path.includes('/live-status')) return 'LIVE-STATUS-SCREEN';
      if (path.includes('/hry-transco'))
        return 'HIERARCHY-TRANSCODIFICATION-SCREEN';

      appLogger.debug(
        '[getAppName] Falling back to default: LIVE-STATUS-SCREEN',
      );
      return 'LIVE-STATUS-SCREEN';
    },

    async getUser(): Promise<User | undefined> {
      if (this.user) {
        return this.user;
      }
      const user = await getUser();
      if (user) {
        this.user = user;
      }
      return user;
    },

    async initializeAuthentication() {
      const router = useRouter();
      const appName = this.getAppName();
      await initializeAppAuth(appName, router);
    },

    async isAuthenticated(): Promise<boolean> {
      const appName = this.getAppName();
      const authService = getAuthService(appName);
      return authService.isAuthenticated();
    },

    async logout() {
      try {
        const appName = this.getAppName();
        await logoutApp(appName);
      } catch (error) {
        appLogger.error(`Log out failed: ${error}`);
      }
    },
  },

  persist: {
    key: (): string => {
      return `userAttributes`;
    },
    paths: ['userAttributes'],
  },

  state: (): State => ({
    managedBy: '',
    profile: '',
    user: undefined,
    userAttributes: {},
  }),
});

