// Shared helpers for ShiftTrackingTable and widgets
/**
 * Remove leading zeros from a string or number
 * @param value - The value to process
 * @returns The value as a string without leading zeros
 */
export function removeLeadingZeros(value: string | number): string {
  return String(value).replace(/^0+/, '');
}

/**
 * Removes leading zeros from a string containing numbers, handling both single numbers and semicolon-separated multiple numbers.
 * @param input - The input string containing number(s) to process
 * @returns The processed string with leading zeros removed, or '0' if the result would be empty
 */
export function removeLeadingZeros(input: string): string {
  if (!input) return ''; // Handle empty input

  // If there's a semicolon, treat it as multiple numbers
  if (input.includes(';')) {
    return input
      .split(';')
      .map((part) => part.replace(/^0+/, '') || '0')
      .join(';');
  }
  // Single number case
  return input.replace(/^0+/, '') || '0';
}

