import { createRouter, createWebHistory } from 'vue-router';
import { useProfileStore } from '@/Auth/store/user-auth-store';
import unauthorized from '@/global-components/Unauthorized.vue';
import loadingComponent from '@/global-components/loading.vue';
import { getI18nInstance, supportedLocales } from '@/localization/i18n';
import { routes as dashBoardRoutes } from '@/modules/epart-board/router/routes';
import { routes as hryTranscoRoutes } from '@/modules/hry-transco/router/routes';
import { routes as liveStatusRoutes } from '@/modules/live-status/router/routes';
import appLogger from '@/utils/logger/app-logger.ts';

const appRedirectUri = import.meta.env.APP_REDIRECT_URI;
let appBasePath: string | undefined;
if (appRedirectUri) {
  const parts = appRedirectUri.split('/');
  appBasePath = parts.pop();
}
const router = createRouter({
  history: createWebHistory(),
  routes: [],
});
const routes = [
  ...dashBoardRoutes,
  ...liveStatusRoutes,
  ...hryTranscoRoutes,
  {
    component: Logout,
    name: 'Logout',
    path: '/logout',
    props: {
      onLoginAgain: (): void => {
        const profileStore = useProfileStore();
        profileStore.initializeAuthentication();
        router.push(`/${appBasePath}/unauthorized`);
      },
    },
  },
  {
    component: unauthorized,

    name: 'Unauthorized',
    path: `/${appBasePath}/unauthorized`,
  },
  {
    component: loadingComponent,
    name: 'LoadingComponent',
    path: '/loading',
  },
];

for (const r of routes) {
  router.addRoute(r);
}

router.beforeEach(async (to, _from, next) => {
  // Apply locale from /epb-ui/:language if valid
  const languageParameter = to.params.language as string | undefined;
  if (
    languageParameter &&
    supportedLocales.includes(
      languageParameter as unknown as (typeof supportedLocales)[number],
    )
  ) {
    const instance = getI18nInstance();
    if (instance && instance.global.locale !== languageParameter) {
      (instance.global as { locale: string }).locale = languageParameter;
    }
  }
  if (to.meta.title) {
    document.title = `MESX.0 - ${to.meta.title as string}`;
  }
  const userAuth = useProfileStore();
  if (to.meta.requiresAuth) {
    // Pass the route object directly for proper meta access
    const appName = userAuth.getAppName(to);
    try {
      await userAuth.authenticateUser(appName);
      const user = await userAuth.getUser();
      if (user) {
        await userAuth.fetchUserAttributes(appName);
        await userAuth.authorizeUser(appName);
      } else {
        console.error('[router] User not found after authenticateUser');
        return next(`/${appBasePath}/unauthorized`);
      }
      return next();
    } catch (error) {
      appLogger.error(`Error during authentication or authorization: ${error}`);
      console.error('[router] auth error', error);
      return next(`/${appBasePath}/unauthorized`);
    }
  }
  return next(); // Explicit return for non-authenticated routes
});
export { router };

