import { createI18n, I18n } from 'vue-i18n';
// Import { useLocaleStore } from '../modules/picking-screen/store/local-store.ts';
import cz from './locales/cz.json';
import en from './locales/en.json';
import es from './locales/es.json';
import fr from './locales/fr.json';
import pt from './locales/pt.json';

/**
 * Setup the i18n instance with the selected locale and available messages.
 * @returns A promise that resolves to the i18n instance.
 */
export const supportedLocales = ['en', 'fr', 'es', 'pt', 'cz'] as const;
export type SupportedLocale = (typeof supportedLocales)[number];

let i18nInstance: I18n | undefined;

/**
 * Initialize and return the i18n instance.
 * @param initialLocale Optional locale seed (must be in supportedLocales) otherwise defaults to 'en'.
 * @returns The created i18n instance.
 */
export async function setupI18n(initialLocale?: string): Promise<I18n> {
  const locale =
    initialLocale && supportedLocales.includes(initialLocale as SupportedLocale)
      ? (initialLocale as SupportedLocale)
      : 'en';
  i18nInstance = createI18n({
    locale,
    fallbackLocale: 'en',
    messages: { cz, en, es, fr, pt },
  });
  return i18nInstance;
}

/**
 * Access the already created i18n instance (undefined until setupI18n is called).
 * @returns The existing i18n instance or undefined if not initialized.
 */
export function getI18nInstance(): I18n | undefined {
  return i18nInstance;
}

import ganttastic from '@infectoone/vue-ganttastic';
import mainHeader, { NotifyPlugin } from '@mesx/common-ui-lib';
import { createPinia } from 'pinia';
import piniaPluginPersistedstate from 'pinia-plugin-persistedstate';
import { Quasar, Notify } from 'quasar';
import { createApp } from 'vue';
import App from './App.vue';
import { router } from '@/global-router/index.ts';
import { setupI18n } from '@/localization/i18n.ts';
import { useHierarchyStore } from '@/shared-stores/hierarchy-store';
import 'floating-vue/dist/style.css';

import '@mesx/common-ui-lib/style.css';
import './css/tailwind.css';
import './styles/tokens.css';

/**
 * Initializes the application by setting up necessary configurations, services, or data.
 * This function is typically called when the app starts.
 * @returns A promise that resolves when the initialization is complete.
 */
async function initializeApp(): Promise<void> {
  const pinia = createPinia();
  const app = createApp(App);

  app.use(Quasar, {
    config: {
      //   Notify: /* look at QuasarConfOptions from the API card */
    },
    plugins: {
      Notify,
    },
  });
  app.use(pinia);
  pinia.use(piniaPluginPersistedstate);
  app.use(router);
  try {
    const i18n = await setupI18n();
    app.use(i18n);
  } catch (error) {
    console.error('Failed to initialize i18n:', error);
  }
  app.use(mainHeader);
  const { $q } = app.config.globalProperties;

  app.use(NotifyPlugin, { $q });

  // Always reset hierarchy selection on each full page refresh so user must reselect context.
  const hierarchyStore = useHierarchyStore();
  hierarchyStore.resetHierarchy();
  app.use(ganttastic);
  app.mount('#app');
}
initializeApp();

