/* Service to fetch next planned stoppage event (aligned with scrap-api token/header pattern) */
const token = import.meta.env.TOKEN;
const edashboardBackendBaseUrl = import.meta.env.EPART_BOARD_BACKEND_URL;

export interface NextPlannedStoppageDto {
  ticket?: string;
  plant?: number;
  startDate?: string; // ISO camelCase
  endDate?: string;
  status?: string;
  cause?: number;
  cause1?: string | null;
  cause2?: string | null;
  resource?: string;
  remark?: string | null;
  duration?: number;
  plannedStoppageId?: number;
  [key: string]: unknown;
}

export class PlannedStoppageApiService {
  public static async getNextPlannedStoppage(
    plant: string | number,
    resource: string,
    startShift: string,
    endShift: string,
  ): Promise<NextPlannedStoppageDto | undefined> {
    try {
      if (!edashboardBackendBaseUrl) {
        console.warn(
          'PlannedStoppageApiService.getNextPlannedStoppage - missing EPART_BOARD_BACKEND_URL',
        );
        return undefined;
      }

      const queryParameters = new URLSearchParams();
      queryParameters.append('plant', plant.toString());
      queryParameters.append('resource', resource);
      // Normalize to UTC to match database timezone (UTC+0)
      const startUtcIso = new Date(startShift).toISOString();
      const endUtcIso = new Date(endShift).toISOString();
      queryParameters.append('startShift', startUtcIso);
      queryParameters.append('endShift', endUtcIso);

      const url = `${edashboardBackendBaseUrl}/epart-board/next-planned-stoppage?${queryParameters.toString()}`;
      const headers: Record<string, string> = {
        contentType: 'application/json',
      };
      if (token) {
        headers.authorization = `Bearer ${token}`;
      }

      const response = await fetch(url, {
        credentials: 'include',
        headers,
        method: 'GET',
      });

      if (!response.ok) {
        console.warn(
          `PlannedStoppageApiService.getNextPlannedStoppage - API call failed ${response.status}: ${response.statusText}`,
        );
        return undefined;
      }

      // Check if response has content before parsing JSON
      const text = await response.text();
      if (!text || text.trim() === '') {
        // Empty response - no planned stoppage found
        return undefined;
      }

      const data = JSON.parse(text) as NextPlannedStoppageDto;
      return data;
    } catch (error) {
      console.error(
        'PlannedStoppageApiService.getNextPlannedStoppage - Unexpected error',
        error instanceof Error ? error.message : String(error),
      );
      return undefined;
    }
  }
}

