/**
 * Normalizes API message payloads into a single string.
 * @param message Raw message payload from the API.
 * @returns A human-readable message when one exists.
 */
function normalizeApiMessage(
  message?: ConfigureBalancingResponse['message'],
): string | undefined {
  if (Array.isArray(message)) {
    return message.filter(Boolean).join(', ');
  }

  return message;
}

export class ShiftApiService {
  public static async getBalancingAvailability(
    parameters?: BalancingAvailabilityParameters,
  ): Promise<BalancingAvailabilityResponse | undefined> {
    try {
      const profileStore = useProfileStore();
      const plant = parameters?.plant ?? profileStore.userAttributes?.plant;
      const resourceId =
        parameters?.resourceId ?? useHierarchyStore().resource ?? '';

      if (!plant || !resourceId) return undefined;

      const headers: Record<string, string> = {
        contentType: 'application/json',
      };
      if (token) {
        headers.authorization = `Bearer ${token}`;
      }

      const query = new URLSearchParams({
        plant: String(plant),
        resourceId,
      });

      const response = await fetch(
        `${edashboardBackendBaseUrl}/epart-board/balancing/availability?${query.toString()}`,
        {
          method: 'GET',
          headers,
          credentials: 'include',
        },
      );

      if (!response.ok) {
        return undefined;
      }
      return (await response.json()) as BalancingAvailabilityResponse;
    } catch {
      return undefined;
    }
  }

  public static async getBalancingOptions(
    parameters?: BalancingOptionsParameters,
  ): Promise<BalancingOptionsResponse | undefined> {
    try {
      const profileStore = useProfileStore();
      const plant = parameters?.plant ?? profileStore.userAttributes?.plant;
      const resourceId =
        parameters?.resourceId ?? useHierarchyStore().resource ?? '';

