      };
      if (token) {
        headers.authorization = `Bearer ${token}`;
      }

      const query = new URLSearchParams({
        plant: String(plant),
        resourceId,
        ...(parameters?.shiftCode ? { shiftCode: parameters.shiftCode } : {}),
      });

      const response = await fetch(
        `${edashboardBackendBaseUrl}/epart-board/balancing/options?${query.toString()}`,
        {
          method: 'GET',
          headers,
          credentials: 'include',
        },
      );

      if (!response.ok) {
        return undefined;
      }
      return (await response.json()) as BalancingOptionsResponse;
    } catch {
