    }
  }

  public static async configureBalancing(
    parameters: ConfigureBalancingParameters,
  ): Promise<ConfigureBalancingResult> {
    try {
      const headers: Record<string, string> = {};
      headers['content-type'] = 'application/json';
      if (token) {
        headers.authorization = `Bearer ${token}`;
      }

      const response = await fetch(
        `${edashboardBackendBaseUrl}/epart-board/balancing/configure`,
        {
          method: 'POST',
          headers,
          credentials: 'include',
          body: JSON.stringify(parameters),
        },
      );

      let payload: ConfigureBalancingResponse | undefined;
      try {
        payload = (await response.json()) as ConfigureBalancingResponse;
      } catch {
        payload = undefined;
      }

      if (!response.ok) {
        return {
          success: false,
          message:
            normalizeApiMessage(payload?.message) ??
            payload?.error ??
            `Request failed (${response.status})`,
        };
      }

      if (payload?.success === true) {
        return { success: true };
      }

      return {
        success: false,
        message: normalizeApiMessage(payload?.message) ?? 'Write-back failed.',
      };
    } catch {
      return {
        success: false,
        message: 'Write-back failed.',
      };
    }
  }

  public static async getShiftInfo(): Promise<ShiftApiData | undefined> {
