    }
  }

  public static async getShiftData(
    context?: ShiftApiData,
  ): Promise<Array<ShiftProductionItem> | undefined> {
    let contextData: ShiftApiData | undefined;
    try {
      contextData = context || (await ShiftApiService.getShiftInfo());
      const current = contextData?.currentShift;
      const dashboardStore = useDashboardStore();
      dashboardStore.setStartDatetime(current?.startDatetime);
      dashboardStore.setEndDatetime(current?.endDatetime);

      const { plant, resource: resourceId } = useHierarchyStore();
      if (!current) {
        return undefined;
      }
      const start = current.startDatetime;
      const end = current.endDatetime;
      const profileStore = useProfileStore();
      const timezone = profileStore.userAttributes?.timezone;
      const parameters = new URLSearchParams({
        plant: plant.toString(),
        resourceId,
        shiftEndDate: end,
        shiftStartDate: start,
        ...(timezone ? { timezone } : {}),
      });
      const url = `${edashboardBackendBaseUrl}/epart-board/hourly-aggregation?${parameters.toString()}`;
      const headers: Record<string, string> = {
        contentType: 'application/json',
      };
      if (token) {
        headers.authorization = `Bearer ${token}`;
      }
      const response = await fetch(url, {
        method: 'GET',
        headers,
        credentials: 'include', // Include cookies for authentication
      });
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }
      const apiResponse = await response.json();
      const normalized: Array<NormalizedHourlyItem> = Object.keys(apiResponse)
        .filter((k) => /^\d+$/.test(k))
        .map((k) => apiResponse[k] as HourlyAggregatedProductionDto)
        .map((item) => {
          let hourLabel = '';
          if (item.dateHourFrom && item.dateHourFrom.length >= 16) {
            const hh = item.dateHourFrom.slice(11, 13);
            const mm = item.dateHourFrom.slice(14, 16);
            hourLabel = `${hh}:${mm}`;
          } else if (item.hour) {
            const rawHour = item.hour.toString();
            hourLabel = `${rawHour.padStart(2, '0')}:00`;
          }
          let cause: 'green' | 'yellow' | 'red' | 'grey' = 'green';
          if (item.delta < -20) cause = 'red';
          else if (item.delta < 0) cause = 'yellow';
          else if (item.target === 0 && item.production === 0) cause = 'grey';
          const hasSpeed =
            typeof item.speed === 'string' && item.speed.trim() !== '';
          return {
            cause,
            causeNumber: item.causeNumber,
            comments: item.comments,
            delta: item.delta,
            description: item.description,
            hour: hourLabel,
            mostRecentTicket: item.mostRecentTicket,
            prod: item.production,
            ref: item.material,
            slot: item.status,
            slotMode: hasSpeed ? 'SPEED' : 'STATUS',
            slowdown: item.slowdown,
            speed: hasSpeed ? item.speed : undefined,
            target: item.target,
            ucTicket: item.ucTicket,
            tool: item.tool ?? '',
          };
        });
      return normalized.map<ShiftProductionItem>((n) => ({
        cause: n.cause,
        causeNumber: n.causeNumber,
        comments: n.comments,
        description: n.description,
        hour: n.hour,
        mostRecentTicket: n.mostRecentTicket,
        prod: n.prod,
        ref: { type: 'batch', value: n.ref },
        slot: n.slot,
        slotMode: n.slotMode,
        slowdown: n.slowdown,
        speed: n.speed,
        target: n.target,
        tool: n.tool,
        ucTicket: n.ucTicket,
      }));
    } catch {
      return undefined;
    }
  }

