  public static async writeSlowdownComment(parameters: {
    selectedHour: string;
    comment: string;
  }): Promise<boolean> {
    try {
      const { plant, resource } = useHierarchyStore();
      const profileStore = useProfileStore();
      const timezone = profileStore.userAttributes?.timezone;

      if (!plant || !resource) {
        throw new Error('Missing plant or resource');
      }

      const { startDateTime, endDateTime } = this.buildHourRange(
        parameters.selectedHour,
        timezone,
      );
      const writeDateTime = this.formatDateTime(new Date());
      const headers: Record<string, string> = {
        contentType: 'application/json',
      };
      if (token) {
        headers.authorization = `Bearer ${token}`;
      }
      const query = new URLSearchParams({
        actionType: 'HOUR_ACTION',
        comment: parameters.comment,
        endDateTime,
        plant,
        resource,
        startDateTime,
        writeDateTime,
      });
      const response = await fetch(
        `${edashboardBackendBaseUrl}/epart-board/writeBackDescription?${query.toString()}`,
        {
          method: 'POST',
          headers,
          credentials: 'include',
        },
      );

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      return true;
    } catch (error) {
      console.error('Slowdown write-back failed', error);
      return false;
    }
  }

  private static pad(n: number): string {
    return n.toString().padStart(2, '0');
  }

  public static formatDateTime(date: Date): string {
    return (
      `${this.pad(date.getMonth() + 1)}/${this.pad(date.getDate())}/${date.getFullYear()} ` +
      `${this.pad(date.getHours())}:${this.pad(date.getMinutes())}:${this.pad(date.getSeconds())}`
    );
  }

  public static buildHourRange(
    selectedHour: string,
    timezone?: string,
  ): {
    startDateTime: string;
    endDateTime: string;
  } {
    if (!selectedHour) {
      throw new Error('selectedHour is required');
    }

    const [hourString, minuteString = '00'] = selectedHour.split(':');
    const hour = Number(hourString);
    const minute = Number(minuteString);

    if (Number.isNaN(hour) || hour < 0 || hour > 23) {
      throw new Error('Invalid hour');
    }
    if (Number.isNaN(minute) || minute < 0 || minute > 59) {
      throw new Error('Invalid minute');
    }

    // Get base date (today) in timezone or local
    let year: number;
    let month: number;
    let day: number;

    if (timezone) {
      const formatter = new Intl.DateTimeFormat('en-US', {
        timeZone: timezone,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
      });

      const parts = formatter.formatToParts(new Date());
      year = Number(parts.find((p) => p.type === 'year')?.value);
      month = Number(parts.find((p) => p.type === 'month')?.value);
      day = Number(parts.find((p) => p.type === 'day')?.value);
    } else {
      const now = new Date();
      year = now.getFullYear();
      month = now.getMonth() + 1;
      day = now.getDate();
    }

    const startDateTime = `${this.pad(month)}/${this.pad(day)}/${year} ${this.pad(hour)}:${this.pad(minute)}:00`;

    let endYear = year;
    let endMonth = month;
    let endDay = day;
    let endHour = hour + 1;

    if (endHour === 24) {
      endHour = 0;

      const nextDay = new Date(year, month - 1, day + 1);
      endYear = nextDay.getFullYear();
      endMonth = nextDay.getMonth() + 1;
      endDay = nextDay.getDate();
    }

    const endDateTime =
      `${this.pad(endMonth)}/${this.pad(endDay)}/${endYear} ` +
      `${this.pad(endHour)}:${this.pad(minute)}:00`;

    return {
      startDateTime,
      endDateTime,
    };
  }
}

