      const total = state.shiftData.reduce(
        (accumulator, shift) => {
          return {
            target: accumulator.target + shift.target,
            produced: accumulator.produced + shift.produced,
          };
        },
        { target: 0, produced: 0 },
      );
      return total.produced - total.target;
    },

