    setEndDatetime(endDatetime: string | undefined): void {
      this.$state.endDatetime = endDatetime;
    },
    setStartDatetime(startDatetime: string | undefined): void {
      this.$state.startDatetime = startDatetime;
    },
    updateShift(shift: string): void {
      this.$state.currentShift = shift;
    },

    updateShiftInfo(shiftData: Partial<DashboardState['shiftInfo']>): void {
      this.shiftInfo = { ...this.shiftInfo, ...shiftData };
    },

    setActiveShift(shiftType: keyof DashboardState['shiftInfo']): void {
      for (const key of Object.keys(this.shiftInfo)) {
        (this.shiftInfo as any)[key].isActive = false;
      }

      if (this.shiftInfo[shiftType]) {
        this.shiftInfo[shiftType].isActive = true;
      }
    },

    updateShiftProductionData(productionData: any): void {
      this.shiftProductionData = productionData;
    },

    setActiveView(view: string): void {
      this.activeView = view;
      const mainTabs = ['popis', 'kontrola', 'stav'];
      if (mainTabs.includes(view)) {
        localStorage.setItem('lastMainTab', view);
      }
    },

    returnToMainView(): string {
      const lastMainTab = localStorage.getItem('lastMainTab') || 'kontrola';
      this.activeView = lastMainTab;
      return lastMainTab;
    },

    updateKPI(type: string, data: Partial<KPIData>): void {
      if (this.kpiData[type]) {
        this.kpiData[type] = { ...this.kpiData[type], ...data };
      }
    },

    updateProductionMetrics(metrics: Partial<ProductionMetrics>): void {
      this.productionMetrics = { ...this.productionMetrics, ...metrics };
    },

    updateShiftData(timeSlot: string, data: Partial<ShiftData>): void {
      const index = this.shiftData.findIndex(
        (shift) => shift.time === timeSlot,
      );
      if (index !== -1) {
        this.shiftData[index] = { ...this.shiftData[index], ...data };
      }
    },

    updatePopisTaskStatus(taskId: number, status: Task['status']): void {
      const index = this.popisData.tasks.findIndex(
        (task) => task.id === taskId,
      );
      if (index !== -1) {
        this.popisData.tasks[index].status = status;
        this.recalculatePopisStats();
      }
    },

    recalculatePopisStats(): void {
      const ok = this.popisData.tasks.filter((t) => t.status === 'ok').length;
      const nok = this.popisData.tasks.filter((t) => t.status === 'nok').length;
      const notDone = this.popisData.tasks.filter(
        (t) => t.status === 'not-done',
      ).length;
      this.popisData.stats = { ok, nok, notDone };
    },

    fetchRealTimeData(): void {
      const now = new Date();
      this.currentTime = now.toLocaleTimeString('fr-FR', {
        hour: '2-digit',
        minute: '2-digit',
      });

      const randomVariation = (): number => Math.floor(Math.random() * 3) - 1;
      this.productionMetrics.produced += randomVariation();
      this.productionMetrics.hourlyDelta += randomVariation();

      const endTime = new Date();
      endTime.setHours(endTime.getHours() + 1);
      endTime.setMinutes(0);
      endTime.setSeconds(0);

      const diffMs = endTime.getTime() - now.getTime();
      const diffMins = Math.floor(diffMs / 60_000);
      const diffSecs = Math.floor((diffMs % 60_000) / 1000);

      this.productionMetrics.shiftEndTime = `${String(diffMins).padStart(2, '0')}:${String(diffSecs).padStart(2, '0')}`;
    },

    startRealTimeUpdates(): void {
      this.fetchRealTimeData();
      setInterval(() => {
        this.fetchRealTimeData();
      }, 30_000);
    },
  },
});

