    getTasksByStatus:
      (state) =>
      (status: Task['status']): Array<Task> => {
        return state.stations.flatMap((station) =>
          station.tasks.filter((task) => task.status === status),
        );
      },

    getTotalTasksCount: (state): number => {
      return state.stations.reduce(
        (total, station) => total + station.tasks.length,
        0,
      );
    },

    getCompletedTasksCount: (state): number => {
      return state.stations.reduce(
        (total, station) =>
          total +
          station.tasks.filter((task) => task.status === 'completed').length,
        0,
      );
    },

    getPendingTasksCount: (state): number => {
      return state.stations.reduce(
        (total, station) =>
          total +
          station.tasks.filter((task) => task.status === 'pending').length,
        0,
      );
    },

    getTasksCountByType: (state): Record<string, number> => {
      const counts: Record<string, number> = {};
      for (const type of Object.keys(state.taskTypes)) {
        counts[type] = state.stations.reduce(
          (total, station) =>
            total + station.tasks.filter((task) => task.type === type).length,
          0,
        );
      }
      return counts;
    },
  },

  actions: {
    updateTaskStatus(
      stationId: string,
      taskId: string,
      status: Task['status'],
    ): void {
      const station = this.stations.find((s) => s.id === stationId);
      if (station) {
        const task = station.tasks.find((t) => t.id === taskId);
        if (task) {
          task.status = status;
          task.updatedAt = new Date().toISOString();
        }
      }
    },

    addTask(
      stationId: string,
      task: Omit<Task, 'id' | 'createdAt' | 'status'>,
    ): void {
      const station = this.stations.find((s) => s.id === stationId);
      if (station) {
        const newTask: Task = {
          ...task,
          id: `${task.type}_${Date.now()}`,
          createdAt: new Date().toISOString(),
          status: 'pending',
        };
        station.tasks.push(newTask);
      }
    },

    removeTask(stationId: string, taskId: string): void {
      const station = this.stations.find((s) => s.id === stationId);
      if (station) {
        const index = station.tasks.findIndex((t) => t.id === taskId);
        if (index !== -1) {
          station.tasks.splice(index, 1);
        }
      }
    },

    updateTask(
      stationId: string,
      taskId: string,
      updates: Partial<Task>,
    ): void {
      const station = this.stations.find((s) => s.id === stationId);
      if (station) {
        const task = station.tasks.find((t) => t.id === taskId);
        if (task) {
          Object.assign(task, updates, { updatedAt: new Date().toISOString() });
        }
      }
    },

    filterTasks(criteria: TaskCriteria): Array<Task> {
      return this.stations.flatMap((station) =>
        station.tasks.filter((task) => {
          return Object.entries(criteria).every(([key, value]) => {
            if (Array.isArray(value)) {
              return value.includes((task as any)[key]);
            }
            return (task as any)[key] === value;
          });
        }),
      );
    },
  },
});

