import axios, { AxiosResponse } from 'axios';
import type {
  GapData,
  AssignGapToResourcesRequest,
  AssignGapToResourcesResponse,
  UnassignGapFromResourceRequest,
  UnassignGapFromResourceResponse,
} from '@/types/gap-api.types';

export class GapApiService {
  private readonly epartBoardBackendUrl: string;

  private readonly token: string;

  /**
   * Assign a gap to multiple resources
   * @param plant - The plant identifier (as string, will be converted to number)
   * @param resourceIds - Array of resource IDs to assign the gap to
   * @param gapId - The gap ID to assign
   * @param gapDesc - The gap description to assign
   * @returns Promise with assignment response
   */
  public assignGapToResources = async (
    plant: string,
    resourceIds: Array<string>,
    gapId: string,
    gapDesc?: string,
  ): Promise<AssignGapToResourcesResponse> => {
    try {
      const plantNumber = Number(plant);
      const request: AssignGapToResourcesRequest = {
        plant: plantNumber,
        resourceIds,
        gapId,
        gapDesc,
      };

      const headers: Record<string, string> = {
        contentType: 'application/json',
      };

      if (this.token) {
        headers.authorization = `Bearer ${this.token}`;
      }

      const response: AxiosResponse<AssignGapToResourcesResponse> =
        await axios.post(
          `${this.epartBoardBackendUrl}/egap-board/assign-gap-to-resources`,
          request,
          {
            headers,
          },
        );

      return response.data;
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Failed to assign gap';
      throw new Error(`Failed to assign gap to resources: ${errorMessage}`);
    }
  };

  /**
   * Unassign a gap from a resource
   * @param plant - The plant identifier (as string, will be converted to number)
   * @param resourceId - The resource ID to unassign the gap from
   * @param gapId - The gap ID to unassign
   * @returns Promise with unassignment response
   */
  public unassignGapFromResource = async (
    plant: string,
    resourceId: string,
    gapId: string,
  ): Promise<UnassignGapFromResourceResponse> => {
    try {
      const plantNumber = Number.parseInt(plant, 10);
      const request: UnassignGapFromResourceRequest = {
        plant: plantNumber,
        resourceId,
        gapId,
      };

      const headers: Record<string, string> = {
        contentType: 'application/json',
      };

      if (this.token) {
        headers.authorization = `Bearer ${this.token}`;
      }

      const response: AxiosResponse<UnassignGapFromResourceResponse> =
        await axios.post(
          `${this.epartBoardBackendUrl}/egap-board/unassign-gap-from-resource`,
          request,
          {
            headers,
          },
        );

      return response.data;
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Failed to unassign gap';
      throw new Error(`Failed to unassign gap from resource: ${errorMessage}`);
    }
  };

  public constructor(_epartBoardBackendUrl: string, _authToken?: string) {
    this.epartBoardBackendUrl = _epartBoardBackendUrl;
    this.token = _authToken || '';
  }

  /**
   * Fetch all gaps for a specific plant from mLean
   * @param plant - The plant identifier
   * @returns Promise with array of gap data
   */
  public async getGapMleanList(plant: string): Promise<Array<GapData>> {
    try {
      // Original API call (commented out for now)
      const headers: Record<string, string> = {};

      if (this.token) {
        headers.Authorization = `Bearer ${this.token}`;
      }

      const response: AxiosResponse = await axios.get(
        `${this.epartBoardBackendUrl}/egap-board/gap-mlean-list/${plant}`,
        {
          headers,
        },
      );
      return response.data || [];
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Failed to fetch gaps';
      throw new Error(`Failed to fetch gaps from mLean: ${errorMessage}`);
    }
  }
}

/**
 * Configuration Service
 * Centralized configuration for API and authentication
 */

import { useProfileStore } from '@/Auth/store/user-auth-store';

export interface ApiConfig {
  baseUrl: string;
  token?: string;
  plant: string;
}

/**
 * Get the current API configuration
 * Combines environment variables and user auth data
 * @returns The API configuration object
 */
export const getApiConfig = (): ApiConfig => {
  try {
    const userStore = useProfileStore();

    const baseUrl = import.meta.env.EPART_BOARD_BACKEND_URL;
    const token = import.meta.env.TOKEN;
    const plant = userStore.userAttributes?.plant;

    return {
      baseUrl,
      ...(token && { token }),
      plant,
    };
  } catch (error) {
    console.error('Failed to get API config:', error);
    // Return safe defaults
    return {
      baseUrl: '',
      plant: '',
    };
  }
};

import { defineStore } from 'pinia';
import type {
  GapData,
  SelectedResourceData,
  State,
} from '@/types/hry-transco.types';
import type { Resource } from '@/types/resource.types';
import type { UAP } from '@/types/uap.types';

export const useHryTranscoStore = defineStore('hry-transco', {
  state: (): State => ({
    // Assignment state
    assignmentResource: { id: '', name: '', hierarchy: '' },
    gapData: {},
    isAssigning: false,
    isUnassigning: false,

    // Gap management
    availableGaps: [],
    gapsError: undefined,
    isLoadingGaps: false,

    // Resource hierarchy
    isLoadingResources: false,
    resources: [],
    resourcesError: undefined,

    // Selection state
    selectedGap: '',
    selectedResources: [],

    // UI state
    resourceToUnassign: undefined,
    searchQuery: '',
    showAssignmentModal: false,
    showUnassignModal: false,
  }),

  getters: {
    /**
     * Get all resources flattened from the hierarchy
     * @param state - The current store state
     * @returns An array of all resources flattened from the hierarchy
     */
    allResources: (state) => {
      const flatResources: Array<Resource> = [];
      for (const uap of state.resources) {
        for (const line of uap.productionLines) {
          for (const wc of line.workcenters) {
            flatResources.push(...wc.resources);
          }
        }
      }
      return flatResources;
    },

    /**
     * Get resources assigned to the selected gap
     * @param state - The current store state
     * @returns An array of resources assigned to the selected gap
     */
    assignedResourcesForGap: (state) => {
      if (!state.selectedGap) return [];

      const assignedResources: Array<Resource> = [];
      for (const uap of state.resources) {
        for (const line of uap.productionLines) {
          for (const wc of line.workcenters) {
            for (const resource of wc.resources) {
              if (resource.gap === state.selectedGap) {
                assignedResources.push(resource);
              }
            }
          }
        }
      }
      return assignedResources;
    },

    /**
     * Get selected resources with hierarchy information
     * Filter out resources already assigned to the selected gap
     * @param state - The current store state
     * @returns A list of resources containing hierarchy data (excluding those already assigned to selected gap)
     */
    selectedResourcesData: (state) => {
      const data: Array<SelectedResourceData> = [];
      for (const uap of state.resources) {
        for (const line of uap.productionLines) {
          for (const wc of line.workcenters) {
            for (const resource of wc.resources) {
              if (
                state.selectedResources.includes(resource.id) && // Skip resources already assigned to the selected gap
                (!state.selectedGap || resource.gap !== state.selectedGap)
              ) {
                data.push({
                  gap: resource.gap,
                  gapDesc: resource.gapDesc,
                  hierarchy: `${uap.name} / ${line.name} / ${wc.name}`,
                  id: resource.id,
                  name: resource.name,
                });
              }
            }
          }
        }
      }
      return data;
    },

    /**
     * Check if currently loading any data
     * @param state - The current store state
     * @returns True if any data is currently loading
     */
    isLoading: (state) => state.isLoadingResources || state.isLoadingGaps,
  },

  actions: {
    /**
     * Toggle a resource selection
     * @param resourceId - The ID of the resource to toggle
     */
    toggleResource(resourceId: string) {
      const index = this.selectedResources.indexOf(resourceId);
      if (index > -1) {
        this.selectedResources.splice(index, 1);
      } else {
        this.selectedResources.push(resourceId);
      }
    },

    /**
     * Clear all selected resources
     */
    unselectAll() {
      this.selectedResources = [];
    },

    /**
     * Open assignment modal
     */
    openAssignmentModal() {
      this.showAssignmentModal = true;
    },

    /**
     * Close assignment modal
     */
    closeAssignmentModal() {
      this.showAssignmentModal = false;
    },

    /**
     * Open unassignment modal
     * @param resource - The resource to unassign
     */
    openUnassignModal(resource: Resource) {
      this.resourceToUnassign = resource;
      this.showUnassignModal = true;
    },

    /**
     * Close unassignment modal
     */
    closeUnassignModal() {
      this.showUnassignModal = false;
      this.resourceToUnassign = undefined;
    },

    /**
     * Update search query
     * @param query - The search query string
     */
    updateSearchQuery(query: string) {
      this.searchQuery = query;
    },

    /**
     * Select a gap
     * @param gapId - The ID of the gap to select
     */
    selectGap(gapId: string) {
      this.selectedGap = gapId;
    },

    /**
     * Update resources in hierarchy with new gap assignments
     * @param updatedResourceIds - The list of resource IDs to update
     * @param gapId - The gap ID to assign
     * @param gapDesc - The gap description to assign
     */
    updateResourcesWithGaps(
      updatedResourceIds: Array<string>,
      gapId: string,
      gapDesc?: string,
    ) {
      const finalGapDesc = gapDesc;

      for (const uap of this.resources) {
        for (const line of uap.productionLines) {
          for (const wc of line.workcenters) {
            for (const resource of wc.resources) {
              if (updatedResourceIds.includes(resource.id)) {
                resource.gap = gapId;
                resource.gapDesc = finalGapDesc;
              }
            }
          }
        }
      }
    },

    /**
     * Remove gap from resource
     * @param resourceId - The ID of the resource to remove the gap from
     */
    removeGapFromResource(resourceId: string) {
      for (const uap of this.resources) {
        for (const line of uap.productionLines) {
          for (const wc of line.workcenters) {
            for (const resource of wc.resources) {
              if (resource.id === resourceId) {
                resource.gap = undefined;
              }
            }
          }
        }
      }
    },

    /**
     * Fetch resource hierarchy (stub for API call)
     * This will be called from a composable with proper error handling
     * @param resources - The array of UAP resources to set
     */
    setResources(resources: Array<UAP>) {
      this.resources = resources;
    },

    setResourcesLoading(loading: boolean) {
      this.isLoadingResources = loading;
    },

    setResourcesError(error: string | undefined) {
      this.resourcesError = error;
    },

    /**
     * Set available gaps
     * @param gaps - The array of gap data to set
     */
    setGaps(gaps: Array<GapData>) {
      this.availableGaps = gaps;
    },

    setGapsLoading(loading: boolean) {
      this.isLoadingGaps = loading;
    },

    setGapsError(error: string | undefined) {
      this.gapsError = error;
    },

    /**
     * Set assignment state
     * @param assigning - Whether assignment is in progress
     */
    setAssigning(assigning: boolean) {
      this.isAssigning = assigning;
    },

    setUnassigning(unassigning: boolean) {
      this.isUnassigning = unassigning;
    },
  },
});

