import { computed, unref, watchEffect, type ComputedRef, type Ref } from 'vue';
import type {
  ManagementControlCard,
  ManagementControlFilter,
} from '@/types/management-control.types';

type MaybeReference<T> = T | Ref<T> | ComputedRef<T>;

interface UseManagementControlFiltersOptions {
  cards: MaybeReference<Array<ManagementControlCard>>;
  selectedFilter: Ref<string>;
  allLabel: MaybeReference<string>;
  allBadgeColor?: string;
  fallbackBadgeColor?: string;
}

/**
 * Builds computed management control filters from the given cards and keeps the selected filter in sync with available filters.
 * @param options - Composable options including cards, selectedFilter ref, and labels/colors.
 * @returns An object containing the computed `filters` list.
 */
export function useManagementControlFilters(
  options: UseManagementControlFiltersOptions,
): { filters: ComputedRef<Array<ManagementControlFilter>> } {
  const { selectedFilter } = options;

  const allBadgeColor = options.allBadgeColor ?? '#0024D3';
  const fallbackBadgeColor = options.fallbackBadgeColor ?? '#000100';

  const filters = computed<Array<ManagementControlFilter>>(() => {
    const cards = unref(options.cards);
    const allLabel = unref(options.allLabel);

    const seen = new Map<string, ManagementControlFilter>();

    for (const card of cards) {
      const label = (card.categoryLabel || card.category || 'Other').trim();
      const id = label;
      const badgeColor = card.categoryIconColor || fallbackBadgeColor;

      const existing = seen.get(id);
      if (existing) {
        existing.count += 1;
      } else {
        seen.set(id, {
          badgeColor,
          count: 1,
          id,
          label,
        });
      }
    }

    return [
      {
        badgeColor: allBadgeColor,
        count: cards.length,
        id: 'all',
        label: allLabel,
      },
      ...seen.values(),
    ];
  });

  watchEffect(() => {
    if (selectedFilter.value === 'all') {
      return;
    }

    const available = filters.value.some(
      (filter) => filter.id === selectedFilter.value,
    );

    if (!available) {
      selectedFilter.value = 'all';
    }
  });

  return { filters };
}

