export class ShiftApiService {
  public static async getBalancingAvailability(
    parameters: BalancingAvailabilityParameters,
  ): Promise<BalancingAvailabilityResponse | undefined> {
    try {
      const headers: Record<string, string> = {
        contentType: 'application/json',
      };
      if (token) {
        headers.authorization = `Bearer ${token}`;
      }

      const query = new URLSearchParams({
        plant: parameters.plant,
        resourceId: parameters.resourceId,
      });

      const response = await fetch(
        `${edashboardBackendBaseUrl}/epart-board/balancing/availability?${query.toString()}`,
        {
          method: 'GET',
          headers,
          credentials: 'include',
        },
      );
      if (!response.ok) return undefined;
      return (await response.json()) as BalancingAvailabilityResponse;
    } catch {
      return undefined;
    }
  }

  public static formatShiftProductionDataForUI(
    rows: Array<ShiftProductionItem> | undefined,
  ): Array<FormattedProductionItem> {
    if (!rows) {
      return [];
    }
    return rows.map((it) => {
      const delta = it.prod - it.target;
      const causeNumber = 0;
      const types = ['prod', 'op', 'ps', 'co', 'ls', 'qu', 'uc'];
      const colorMap: Record<string, string> = {
        co: '#00bcd4',
        ls: '#f44336',
        op: '#9c27b0',
        prod: '#4caf50',
        ps: '#607d8b',
        qu: '#ff9800',
        uc: '#9e9e9e',
      };

      // Handle null/undefined slot - use empty string as fallback
      const slotString = it.slot || '';
      const slotSegments = slotString.split(';').map((slotValue) => {
        const trimmed = slotValue.trim();
        if (trimmed === '') {
          return {
            value: -1, // Sentinel for empty
            type: 'empty',
            color: colorMap.uc,
          };
        }
        if (trimmed.toUpperCase() === 'NA') {
          return {
            value: 0, // 'prod' index
            type: 'prod',
            color: colorMap.prod,
          };
        }
        const slotNumber = Number.parseInt(trimmed, 10);
        const type = types[slotNumber] || 'prod';
        return {
          value: slotNumber,
          type,
          color: colorMap[type] || colorMap.uc,
        };
      });
      let referenceIcon;
      switch (it.ref.type) {
        case 'workorder': {
          referenceIcon = 'work';
          break;
        }
        case 'batch': {
          referenceIcon = 'inventory';
          break;
        }
        case 'sebango': {
          referenceIcon = 'qr_code';
          break;
        }
        default: {
          referenceIcon = 'description';
        }
      }

      let causeColor;
      switch (it.cause) {
        case 'green': {
          causeColor = '#28a745';
          break;
        }
        case 'yellow': {
          causeColor = '#ffc107';
          break;
        }
        case 'red': {
          causeColor = '#dc3545';
          break;
        }
        default: {
          causeColor = '#6c757d';
        }
      }
      return {
        cause: it.cause,
        causeColor,
        causeNumber,
        comments: it.comments,
        delta,
        deltaColor: delta >= 0 ? '#28a745' : '#dc3545',
        deltaFormatted: delta >= 0 ? `+${delta}` : `${delta}`,
        description: it.description,
        hour: it.hour,
        mostRecentTicket: it.mostRecentTicket,
        prod: it.prod,
        ref: it.ref.value,
        refIcon: referenceIcon,
        slotOriginal: it.slot,
        slotSegments,
        slowdown: it.slowdown,
        target: it.target,
        tickets: it.tickets,
        ucTicket: it.ucTicket,
      };
    });
  }

  public static async getShiftInfo(): Promise<ShiftApiData | undefined> {
    try {
      const {
        plant: plantId,
        workcenter: workcenterId,
        resource,
      } = useHierarchyStore();
      if (!plantId || !workcenterId || !resource) {
        logger.warn(
          `ShiftApiService.getShiftInfo - Missing required hierarchy fields. This may indicate incomplete user selection or hierarchy configuration issues. Details: plantId=${plantId || 'MISSING'}, workcenterId=${workcenterId || 'MISSING'}, resource=${resource || 'MISSING'}`,
        );
        return undefined;
      }
      const profileStore = useProfileStore();
      const timezone = profileStore.userAttributes?.timezone;
      const dateNow = new Date().toISOString();
      const parameters = new URLSearchParams({
        plantId: plantId.toString(),
        ...(workcenterId ? { workcenterId } : {}),
        timezone: timezone ?? '',
      });
      const url = `${edashboardBackendBaseUrl}/epart-board/shift-context?date=${dateNow}&${parameters}`;
      const headers: Record<string, string> = {
        contentType: 'application/json',
      };
      if (token) {
        headers.authorization = `Bearer ${token}`;
      }

      const response = await fetch(url, {
        method: 'GET',
        headers,
        credentials: 'include', // Include cookies for authentication
      });
      // Only check fetch Response properties if response is a Response object
      if (response instanceof Response) {
        if (!response.ok) {
          logger.error(
            `ShiftApiService.getShiftInfo - API call failed with status ${response.status}: ${response.statusText}. URL: ${url}. This indicates a backend issue or network connectivity problem.`,
          );
          throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }
        const data = await response.json();
        return data as ShiftApiData;
      }
      // If response is already parsed data (array), return undefined (or handle as needed)
      return undefined;
    } catch (error) {
      logger.error(
        'ShiftApiService.getShiftInfo - Unexpected error occurred while fetching shift information. This may be due to network issues, invalid response format, or backend errors.',
        error instanceof Error ? error.message : String(error),
      );
      return undefined;
    }
  }

  public static async getShiftData(
    context?: ShiftApiData,
  ): Promise<Array<ShiftProductionItem> | undefined> {
    try {
      const contextData = context || (await ShiftApiService.getShiftInfo());
      const current = contextData?.currentShift;
      const dashboardStore = useDashboardStore();
      dashboardStore.setStartDatetime(current?.startDatetime);
      dashboardStore.setEndDatetime(current?.endDatetime);

      const { plant, resource: resourceId, gapId, team } = useHierarchyStore();

      // Validate required fields before making API calls
      if (!gapId || !plant || !resourceId) {
        // Clear KPIs and alerts when required fields are missing
        dashboardStore.updateKpisData({});
        dashboardStore.updateAlertCounts({
          grey: 0,
          orange: 0,
          red: 0,
          yellow: 0,
        });
        return undefined;
      }

      if (!current) {
        logger.warn(
          'ShiftApiService.getShiftData - No current shift context available. This may indicate that getShiftInfo() failed to retrieve shift information, possibly due to missing hierarchy fields or API errors.',
        );
        // Clear KPIs and alerts when context is invalid
        dashboardStore.updateKpisData({});
        dashboardStore.updateAlertCounts({
          grey: 0,
          orange: 0,
          red: 0,
          yellow: 0,
        });
        return undefined;
      }
      const start = current.startDatetime;
      const end = current.endDatetime;
      const profileStore = useProfileStore();
      const timezone = profileStore.userAttributes?.timezone;

      // Fetch KPIs in parallel with shift data if gapId is available
      if (plant && gapId && start && end) {
        // Calculate current shift hour number
        const currentShiftHourNumber = ((): number | undefined => {
          try {
            const plantTime = getCurrentTimeInTimezone(timezone);
            const shiftStart = new Date(start);
            const diffMs = plantTime.getTime() - shiftStart.getTime();
            const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
            // Return hour number (1-indexed), e.g., first hour = 1, second hour = 2
            return diffHours >= 0 ? diffHours + 1 : undefined;
          } catch {
            return undefined;
          }
        })();
        getAllMleanKpis({
          currentShiftHourNumber,
          gapId: gapId.toString(),
          plant: plant.toString(),
          shiftEndDate: end,
          shiftStartDate: start,
          teamId: team,
          timezone: timezone || '',
        })
          .then((kpisData) => {
            dashboardStore.updateKpisData(kpisData);
          })
          .catch((error) => {
            logger.error(
              'ShiftApiService.getShiftData - Failed to fetch KPIs data',
              error instanceof Error ? error.message : String(error),
            );
          });
      }

      // Fetch alert counts if plant and resource are available
      if (plant && resourceId) {
        getAlertCountsForResources({
          plant: Number(plant),
          resourceIds: [resourceId],
        })
          .then((alertCountsResponse) => {
            // Since the API returns data for the resource we requested, just use the first item
            const alertData = alertCountsResponse[0] || {
              grey: 0,
              orange: 0,
              red: 0,
              workcenter: '',
              yellow: 0,
            };

            dashboardStore.updateAlertCounts({
              grey: alertData.grey ?? 0,
              orange: alertData.orange ?? 0,
              red: alertData.red ?? 0,
              yellow: alertData.yellow ?? 0,
            });
          })
          .catch((error) => {
            logger.error(
              'ShiftApiService.getShiftData - Failed to fetch alert counts',
              error instanceof Error ? error.message : String(error),
            );
          });
      }

      const parameters = new URLSearchParams({
        plant: plant.toString(),
        resourceId,
        shiftEndDate: end,
        shiftStartDate: start,
        ...(timezone ? { timezone } : {}),
      });
      const url = `${edashboardBackendBaseUrl}/epart-board/hourly-aggregation?${parameters.toString()}`;
      const headers: Record<string, string> = {
        contentType: 'application/json',
      };
      if (token) {
        headers.authorization = `Bearer ${token}`;
      }
      const response = await fetch(url, {
        method: 'GET',
        headers,
        credentials: 'include', // Include cookies for authentication
      });
      if (!response.ok) {
        logger.error(
          `ShiftApiService.getShiftData - API call failed with status ${response.status}: ${response.statusText}. URL: ${url}. This indicates an issue with the hourly aggregation endpoint, possibly due to invalid parameters or backend processing errors.`,
        );
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }
      const apiResponse = await response.json();
      const normalized: Array<NormalizedHourlyItem> = Object.keys(apiResponse)
        .filter((k) => /^\d+$/.test(k))
        .map((k) => apiResponse[k] as HourlyAggregatedProductionDto)
        .map((item) => {
          let hourLabel = '';
          if (item.dateHourFrom && item.dateHourFrom.length >= 16) {
            const hh = item.dateHourFrom.slice(11, 13);
            const mm = item.dateHourFrom.slice(14, 16);
            hourLabel = `${hh}:${mm}`;
          } else if (item.hour) {
            const rawHour = item.hour.toString();
            hourLabel = `${rawHour.padStart(2, '0')}:00`;
          }
          let cause: CauseColor = 'green';
          if (item.delta < -20) cause = 'red';
          else if (item.delta < 0) cause = 'yellow';
          else if (item.target === 0 && item.production === 0) cause = 'grey';
          const hasSpeed =
            typeof item.speed === 'string' && item.speed.trim() !== '';
          return {
            cause,
            causeNumber: item.causeNumber,
            comments: item.comments,
            delta: item.delta,
            description: item.description,
            hour: hourLabel,
            mostRecentTicket: item.mostRecentTicket,
            prod: item.production,
            ref: item.material,
            slot: item.status,
            slotMode: hasSpeed ? 'SPEED' : 'STATUS',
            slowdown: item.slowdown,
            speed: hasSpeed ? item.speed : undefined,
            target: item.target,
            tickets: item.tickets,
            tool: item.tool,
            ucTicket: item.ucTicket,
          };
        });
      return normalized.map<ShiftProductionItem>((n) => ({
        cause: n.cause,
        causeNumber: n.causeNumber,
        comments: n.comments,
        description: n.description,
        hour: n.hour,
        mostRecentTicket: n.mostRecentTicket,
        prod: n.prod,
        ref: { type: 'batch', value: n.ref },
        slot: n.slot,
        slotMode: n.slotMode,
        slowdown: n.slowdown,
        speed: n.speed,
        target: n.target,
        tickets: n.tickets,
        tool: n.tool,
        ucTicket: n.ucTicket,
      }));
    } catch (error) {
      logger.error(
        'ShiftApiService.getShiftData - Unexpected error occurred while fetching shift production data. This may be due to data parsing issues, network failures, or invalid API response structure.',
        error instanceof Error ? error.message : String(error),
      );
      return undefined;
    }
  }

  public static async getFormattedShiftProductionData(
    context?: ShiftApiData,
  ): Promise<Array<FormattedProductionItem>> {
    const raw = await ShiftApiService.getShiftData(context);
    return formatShiftProductionDataForUI(raw);
  }

