    getTotalProduced: (state): number => {
      return state.shiftData.reduce(
        (total, shift) => total + shift.produced,
        0,
      );
    },

    getTotalTarget: (state): number => {
      return state.shiftData.reduce((total, shift) => total + shift.target, 0);
    },

    getOverallDelta: (state): number => {
      let totalTarget = 0;
      let totalProduced = 0;
      for (const shift of state.shiftData) {
        totalTarget += shift.target;
        totalProduced += shift.produced;
      }
      return totalProduced - totalTarget;
    },

    getPopisTasks: (state): Array<Task> => {
      return state.popisData.tasks;
    },

