  actions: {
    async fetchDataForResource(gapId: string) {
      // Example: fetch and update dashboard data for the selected resource
      // You can replace this with your actual API logic
      const resourceGapId = gapId;
      if (resourceGapId) {
        this.fetchRealTimeData();
      }
    },

    fetchRealTimeData(): void {
      const now = new Date();
      this.currentTime = now.toLocaleTimeString('fr-FR', {
        hour: '2-digit',
        minute: '2-digit',
      });

      const randomVariation = (): number => Math.floor(Math.random() * 3) - 1;
      this.productionMetrics.produced += randomVariation();
      this.productionMetrics.hourlyDelta += randomVariation();

      const endTime = new Date();
      endTime.setHours(endTime.getHours() + 1);
      endTime.setMinutes(0);
      endTime.setSeconds(0);

      const diffMs = endTime.getTime() - now.getTime();
      const diffMins = Math.floor(diffMs / 60_000);
      const diffSecs = Math.floor((diffMs % 60_000) / 1000);

      this.productionMetrics.shiftEndTime = `${String(diffMins).padStart(2, '0')}:${String(diffSecs).padStart(2, '0')}`;
    },

    recalculatePopisStats(): void {
      const ok = this.popisData.tasks.filter((t) => t.status === 'ok').length;
      const nok = this.popisData.tasks.filter((t) => t.status === 'nok').length;
      const notDone = this.popisData.tasks.filter(
        (t) => t.status === 'not-done',
      ).length;
      this.popisData.stats = { nok, notDone, ok };
    },

    returnToMainView(): string {
      const lastMainTab = localStorage.getItem('lastMainTab') || 'kontrola';
      this.activeView = lastMainTab;
      return lastMainTab;
    },

    setActiveShift(shiftType: keyof DashboardState['shiftInfo']): void {
      for (const key of Object.keys(this.shiftInfo)) {
        (this.shiftInfo as Record<string, ShiftInfo>)[key].isActive = false;
      }

      if (this.shiftInfo[shiftType]) {
        this.shiftInfo[shiftType].isActive = true;
      }
    },

    setActiveView(view: string): void {
      this.activeView = view;
      const mainTabs = ['popis', 'kontrola', 'stav'];
      if (mainTabs.includes(view)) {
        localStorage.setItem('lastMainTab', view);
      }
    },

    setEndDatetime(endDatetime: string | undefined): void {
      this.$state.endDatetime = endDatetime;
    },

    setStartDatetime(startDatetime: string | undefined): void {
      this.$state.startDatetime = startDatetime;
    },

    startRealTimeUpdates(): void {
      this.fetchRealTimeData();
      setInterval(() => {
        this.fetchRealTimeData();
      }, 30_000);
    },

    updateKPI(type: string, data: Partial<KPIData>): void {
      if (this.kpiData[type]) {
        this.kpiData[type] = { ...this.kpiData[type], ...data };
      }
    },

    updatePopisTaskStatus(taskId: number, status: Task['status']): void {
      const index = this.popisData.tasks.findIndex(
        (task) => task.id === taskId,
      );
      if (index !== -1) {
        this.popisData.tasks[index].status = status;
        this.recalculatePopisStats();
      }
    },

    updateProductionMetrics(metrics: Partial<ProductionMetrics>): void {
      this.productionMetrics = { ...this.productionMetrics, ...metrics };
    },

    updateShift(shift: string): void {
      this.$state.currentShift = shift;
    },

    updateShiftData(timeSlot: string, data: Partial<ShiftData>): void {
      const index = this.shiftData.findIndex(
        (shift) => shift.time === timeSlot,
      );
      if (index !== -1) {
        this.shiftData[index] = { ...this.shiftData[index], ...data };
      }
    },

    updateShiftInfo(shiftData: Partial<DashboardState['shiftInfo']>): void {
      this.shiftInfo = { ...this.shiftInfo, ...shiftData };
    },

    updateShiftProductionData(productionData: unknown): void {
      this.shiftProductionData = productionData;
    },

    updateKpisData(kpisData: AllKpisResponse): void {
      this.kpisData = kpisData;
    },

    updateAlertCounts(alertCounts: {
      grey: number;
      yellow: number;
      orange: number;
      red: number;
    }): void {
      this.alertCounts = alertCounts;
    },

    updateAlertDetails(alertDetails: {
      material: string;
      wkId: string;
      startPickingTime: Date;
      newPromiseTime: Date | null;
      od: string;
      endPreparation: Date | null;
      truckDeparture: Date | null;
      alertStatus: string;
      alertLevel: string;
      alertId: string;
      workcenter: string;
    }): void {
      this.alertDetails = alertDetails;
    },
  },
});

import { defineStore } from 'pinia';

// Types pour le store User
export interface User {
  area: string;
  avatar: string | undefined;
  name: string;
  permissions: Array<string>;
  role: string;
}

export interface UserPreferences {
  theme: 'light' | 'dark';
  language: string;
  autoRefresh: boolean;
  refreshInterval: number;
  notifications: boolean;
}

export interface UserSession {
  loginTime: string;
  lastActivity: string;
  isActive: boolean;
}

export interface UserState {
  currentUser: User;
  preferences: UserPreferences;
  session: UserSession;
}

export const useUserStore = defineStore('user', {
  state: (): UserState => ({
    currentUser: {
      area: '01Line A',
      avatar: undefined,
      name: 'Casey Franklin',
      permissions: [
        'view_dashboard',
        'manage_tasks',
        'start_group',
        'view_layout',
      ],
      role: 'Manager',
    },
    preferences: {
      autoRefresh: true,
      language: 'fr',
      notifications: true,
      refreshInterval: 30_000,
      theme: 'light',
    },
    session: {
      loginTime: new Date().toISOString(),
      lastActivity: new Date().toISOString(),
      isActive: true,
    },
  }),

  getters: {
    hasPermission:
      (state) =>
      (permission: string): boolean => {
        return state.currentUser.permissions.includes(permission);
      },

    getDisplayName: (state): string => {
      return state.currentUser.name;
    },

    getUserInitials: (state): string => {
      return state.currentUser.name
        .split(' ')
        .map((name) => name.charAt(0))
        .join('')
        .toUpperCase();
    },

    isManager: (state): boolean => {
      return state.currentUser.role === 'Manager';
    },

    getSessionDuration: (state): string => {
      const now = new Date();
      const loginTime = new Date(state.session.loginTime);
      const diffMs = now.getTime() - loginTime.getTime();
      const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
      const diffMinutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
      return `${diffHours}h ${diffMinutes}m`;
    },
  },

  actions: {
    updateUser(userData: Partial<User>): void {
      this.currentUser = { ...this.currentUser, ...userData };
      this.updateLastActivity();
    },

    updatePreferences(preferences: Partial<UserPreferences>): void {
      this.preferences = { ...this.preferences, ...preferences };
    },

    updateLastActivity(): void {
      this.session.lastActivity = new Date().toISOString();
    },

    setActiveStatus(isActive: boolean): void {
      this.session.isActive = isActive;
      this.updateLastActivity();
    },

    login(userData: Partial<User>): void {
      this.currentUser = { ...this.currentUser, ...userData };
      this.session.loginTime = new Date().toISOString();
      this.session.isActive = true;
      this.updateLastActivity();
    },

    logout(): void {
      this.session.isActive = false;
    },

    canPerformAction(action: string): boolean {
      const actionPermissions: Record<string, Array<string>> = {
        editSettings: ['manage_tasks'],
        manageTasks: ['manage_tasks'],
        startGroup: ['start_group'],
        viewDashboard: ['view_dashboard'],
        viewLayout: ['view_layout'],
      };

      const requiredPermissions = actionPermissions[action] || [];
      return requiredPermissions.every((permission) =>
        this.currentUser.permissions.includes(permission),
      );
    },
  },
});

