import { DateTime } from 'luxon';
import { computed, ref, type Ref, watch } from 'vue';
import { useProfileStore } from '@/Auth/store/user-auth-store';
import type { CountdownDeps } from '@/types/countdown.types';

/**
 * Shared event countdown + precise refresh scheduling.
 * Ensures an immediate refresh at planned stoppage start or end-of-shift.
 */
/**
 * @param deps Dependencies: timezone, stoppage start, shift end, refresh functions
 * @returns countdown computed values and scheduling helpers
 */
export function useEventCountdown(deps: CountdownDeps): {
  plannedStoppageRemaining: ReturnType<typeof computed<string>>;
  hasFuturePlannedStoppage: ReturnType<typeof computed<boolean>>;
  eventCardCountdown: ReturnType<typeof computed<string>>;
  remainingMsToEvent: ReturnType<typeof computed<number>>;
  scheduleEventRefresh: () => void;
  tickNow: () => void;
  clearEventTimeout: () => void;
  startAutoRefresh: () => void;
  stopAutoRefresh: () => void;
} {
  const nowTick: Ref<number> = ref(Date.now());
  let timeoutId: ReturnType<typeof setTimeout> | undefined;
  let autoRefreshIntervalId: ReturnType<typeof setInterval> | undefined;

  const parseInPlantTz = (dateTime: string, tz: string): DateTime => {
    const isoParsed = DateTime.fromISO(dateTime, { zone: tz });
    if (isoParsed.isValid) return isoParsed;

    // Support SQL-like format used in some test inputs: 'YYYY-MM-DD HH:mm:ss.SSS'
    const sqlParsed = DateTime.fromSQL(dateTime, { zone: tz });
    if (sqlParsed.isValid) return sqlParsed;

    // Last resort: rely on JS Date parsing
    const jsParsed = DateTime.fromJSDate(new Date(dateTime)).setZone(tz);
    return jsParsed;
  };

  // Prefer profile store timezone; fallback to provided deps.timezone
  const profileStore = useProfileStore();
  const tzReference = computed<string>(() => {
    const storeTz = profileStore.userAttributes?.timezone;
    return (storeTz && String(storeTz)) || deps.timezone.value || '';
  });

  const getCurrentTimeInPlantTz = (): DateTime => {
    const tz = tzReference.value || 'UTC';
    return DateTime.now().setZone(tz);
  };

  const plannedStoppageRemaining = computed(() => {
    // Trigger recompute on external tick
    if (nowTick.value < 0) return '';
    if (!deps.nextPlannedStoppageStart.value) return '';
    const plantNow = getCurrentTimeInPlantTz();
    const targetMs = DateTime.fromJSDate(
      deps.nextPlannedStoppageStart.value,
    ).toMillis();
    const diffMs = targetMs - plantNow.toMillis();
    if (diffMs <= 0) return '0m';
    const totalMinutes = Math.floor(diffMs / 60_000);
    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;
    if (hours > 0) return `${hours}h${minutes.toString().padStart(2, '0')}min`;
    return `${minutes}min`;
  });

  const hasFuturePlannedStoppage = computed(() => {
    if (nowTick.value < 0) return false;
    if (!deps.nextPlannedStoppageStart.value) return false;
    const plantNow = getCurrentTimeInPlantTz();
    const targetMs = DateTime.fromJSDate(
      deps.nextPlannedStoppageStart.value,
    ).toMillis();
    const diffMs = targetMs - plantNow.toMillis();
    return diffMs > 0;
  });

  const eventCardCountdown = computed(() => {
    if (nowTick.value < 0) return '';
    if (hasFuturePlannedStoppage.value) return plannedStoppageRemaining.value;
    const endIso = deps.endDatetimeRef.value;
    if (!endIso) return '';
    const tz = tzReference.value || 'UTC';
    const plantNow = getCurrentTimeInPlantTz();
    const endDt = parseInPlantTz(endIso, tz);
    const diffMs = endDt.toMillis() - plantNow.toMillis();
    if (diffMs <= 0) return '0m';
    const totalMinutes = Math.floor(diffMs / 60_000);
    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;
    if (hours > 0) return `${hours}h${minutes.toString().padStart(2, '0')}min`;
    return `${minutes}min`;
  });

  const remainingMsToEvent = computed<number>(() => {
    // Trigger recompute on external tick
    if (nowTick.value < 0) return 0;
    const plantNow = getCurrentTimeInPlantTz();
    let targetMs: number | undefined;
    if (hasFuturePlannedStoppage.value && deps.nextPlannedStoppageStart.value) {
      targetMs = DateTime.fromJSDate(
        deps.nextPlannedStoppageStart.value,
      ).toMillis();
    } else if (deps.endDatetimeRef.value) {
      const tz = tzReference.value || 'UTC';
      targetMs = parseInPlantTz(deps.endDatetimeRef.value, tz).toMillis();
    }
    if (targetMs === undefined) return 0;
    return Math.max(0, targetMs - plantNow.toMillis());
  });

  const scheduleEventRefresh = (): void => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = undefined;
    }
    const plantNow = getCurrentTimeInPlantTz();
    let targetMs: number | undefined;
    if (hasFuturePlannedStoppage.value && deps.nextPlannedStoppageStart.value) {
      targetMs = DateTime.fromJSDate(
        deps.nextPlannedStoppageStart.value,
      ).toMillis();
    } else if (deps.endDatetimeRef.value) {
      const tz = tzReference.value || 'UTC';
      targetMs = parseInPlantTz(deps.endDatetimeRef.value, tz).toMillis();
    }
    if (targetMs === undefined) return;
    const remainingMs = targetMs - plantNow.toMillis();
    if (remainingMs <= 0) return;

    timeoutId = setTimeout(async () => {
      try {
        await deps.refreshFn();
        await deps.fetchPlannedFn();
        nowTick.value = Date.now();
      } finally {
        if (timeoutId) {
          clearTimeout(timeoutId);
          timeoutId = undefined;
        }
      }
    }, remainingMs);
  };

  // Reschedule when inputs change
  watch(
    () => [
      deps.nextPlannedStoppageStart.value,
      deps.endDatetimeRef.value,
      tzReference.value,
    ],
    () => {
      scheduleEventRefresh();
    },
  );

  // Public helpers
  const tickNow = (): void => {
    nowTick.value = Date.now();
  };
  const clearEventTimeout = (): void => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = undefined;
    }
  };

  // Auto-refresh every minute for shift-context, hourly-aggregation, and next-event APIs
  const startAutoRefresh = (): void => {
    if (autoRefreshIntervalId) return; // Already running
    autoRefreshIntervalId = setInterval(async () => {
      try {
        await deps.refreshFn();
        await deps.fetchPlannedFn();
        tickNow();
      } catch (error) {
        console.error('Auto-refresh failed:', error);
      }
    }, 60_000);
  };

  const stopAutoRefresh = (): void => {
    if (autoRefreshIntervalId) {
      clearInterval(autoRefreshIntervalId);
      autoRefreshIntervalId = undefined;
    }
  };

  return {
    clearEventTimeout,
    eventCardCountdown,
    hasFuturePlannedStoppage,
    plannedStoppageRemaining,
    remainingMsToEvent,
    scheduleEventRefresh,
    startAutoRefresh,
    stopAutoRefresh,
    tickNow,
  };
}

import { onMounted, onUnmounted, ref, Ref, watch } from 'vue';
import type {
  ReworkCountResponse,
  ReworkCountParameters,
} from '@/shared-services/scrap-api';
import type { HierarchyStore, DashboardStore } from '@/types/scrap-count.types';

export interface ReworkCountService {
  getReworkCount: (
    parameters: ReworkCountParameters,
  ) => Promise<ReworkCountResponse | undefined>;
}

/**
 * Composable to manage rework count fetching with auto-refresh
 * @param reworkApiService - The API service to fetch rework count
 * @param hierarchyStore - Store containing plant, workcenter, resource
 * @param dashboardStore - Store containing shift start/end datetime
 * @returns Reactive rework count value
 */
export function useReworkCount(
  reworkApiService: ReworkCountService,
  hierarchyStore: HierarchyStore,
  dashboardStore: DashboardStore,
): { reworkCount: Ref<number | undefined> } {
  const reworkCount = ref<number | undefined>(undefined);
  let intervalId: ReturnType<typeof setInterval> | undefined;

  const fetchReworkCount = async (): Promise<void> => {
    const { plant, workcenter, resource } = hierarchyStore;
    const { startDatetime, endDatetime } = dashboardStore;

    if (!plant || !workcenter || !resource || !startDatetime || !endDatetime) {
      reworkCount.value = undefined;
      return;
    }

    try {
      const startDate = new Date(startDatetime).toISOString();
      const endDate = new Date(endDatetime).toISOString();

      const response = await reworkApiService.getReworkCount({
        endDate,
        plant,
        resource,
        startDate,
      });

      reworkCount.value = response?.count;
    } catch (error) {
      console.error('Failed to fetch rework count:', error);
      reworkCount.value = undefined;
    }
  };

  onMounted(async () => {
    if (hierarchyStore.resource) {
      await fetchReworkCount();
    }
    intervalId = setInterval(async () => {
      await fetchReworkCount();
    }, 60_000);
  });

  onUnmounted(() => {
    if (intervalId) {
      clearInterval(intervalId);
      intervalId = undefined;
    }
  });

  watch(
    () => [
      hierarchyStore.resource,
      dashboardStore.startDatetime,
      dashboardStore.endDatetime,
    ],
    async () => {
      await fetchReworkCount();
    },
  );

  return {
    reworkCount,
  };
}

