  UseTreeSelectorReturn,
} from '@/types/tree-selector.types';
import { TreeSelector } from '@/utils/tree-selector';
import { checkResourceIdExists } from '@/utils/utils';

/**
 * Finds details for a specific resource in a hierarchical dataset.
 * @param data - The hierarchical tree data to search.
 * @param resourceId - The unique ID of the resource to locate.
 * @returns The matched resource details object containing managedBy information or undefined if not found.
 */
function findResourceDetails(
  data: Array<unknown>,
  resourceId: string,
): { managedBy?: string } | undefined {
  const found = (data as Array<{ id: string; managedBy?: string }>).find(
    (item) => item.id === resourceId,
  );
  return found ? { managedBy: found.managedBy } : undefined;
}

