let treeSelector: TreeSelector;

/**
 * Composable for managing tree selector logic
 * @param properties - Tree selector properties
 * @returns Tree selector state and methods
 */
export function useTreeSelector(
  properties: TreeSelectorProperties,
): UseTreeSelectorReturn {
  const route = useRoute();
  const router = useRouter();
  const userStore = useUserStore();
  const { t } = useI18n();
  const notify = inject<Notify>('notify');

  // Reactive state
  const treeData = ref<Array<TreeNodeType>>([]);
  const rawData = ref<Array<unknown>>([]);
  const searchQuery = ref('');
  const expandedNodes = ref(new Set<number | string>());
  const selectedNode = ref<TreeNodeType | undefined>(undefined);
  const isLoading = ref(false);
  const isSelectingFromRoute = ref(false);

  treeSelector = new TreeSelector(
    router,
    route,
    userStore,
    properties,
    selectedNode,
    isSelectingFromRoute,
  );

  // Helper functions
  const filterTreeNodes = (
    nodes: Array<TreeNodeType>,
    query: string,
  ): Array<TreeNodeType> => {
    if (!query.trim()) return nodes;

    const filtered: Array<TreeNodeType> = [];
    const lowerQuery = query.trim().toLowerCase();

    const matchesQuery = (node: TreeNodeType): boolean => {
      const label = (node.label || '').toString().toLowerCase();
      const value =
        node.value !== undefined && node.value !== null
          ? String(node.value).toLowerCase()
          : '';
      const resourceId = node.meta?.resourceId
        ? String(node.meta.resourceId).toLowerCase()
        : '';
      const uapId = node.meta?.uapId
        ? String(node.meta.uapId).toLowerCase()
        : '';
      const productionLineId = node.meta?.productionLineId
        ? String(node.meta.productionLineId).toLowerCase()
        : '';
      const workcenterId = node.meta?.workcenterId
        ? String(node.meta.workcenterId).toLowerCase()
        : '';

      return (
        label.includes(lowerQuery) ||
        value.includes(lowerQuery) ||
        resourceId.includes(lowerQuery) ||
        uapId.includes(lowerQuery) ||
        productionLineId.includes(lowerQuery) ||
        workcenterId.includes(lowerQuery)
      );
    };

    const searchInNode = (node: TreeNodeType): TreeNodeType | undefined => {
      const matches = matchesQuery(node);
      const filteredChildren: Array<TreeNodeType> = [];

      if (node.children && node.children.length > 0) {
        for (const child of node.children) {
          const searchResult = searchInNode(child);
          if (searchResult) {
            filteredChildren.push(searchResult);
          }
        }
      }

      if (matches || filteredChildren.length > 0) {
        return {
          ...node,
          children: filteredChildren,
          isSearchMatch: matches, // Flag to indicate direct match
        };
      }

      return undefined;
    };

    for (const node of nodes) {
      const result = searchInNode(node);
      if (result) filtered.push(result);
    }

    return filtered;
  };

  const findResourceNode = (
    nodes: Array<TreeNodeType>,
    parameterValue: string,
    parameterName = 'resourceId',
  ): TreeNodeType | undefined => {
    for (const node of nodes) {
      // Check current node first (regardless of whether it has children)
      if (
        parameterName === 'gapId' &&
        node.meta?.gapId &&
        String(node.meta.gapId) === parameterValue
      ) {
        return node;
      }
      if (
        parameterName === 'resourceId' &&
        node.value === parameterValue &&
        node.meta?.resourceId
      ) {
        return node;
      }

      // Then search in children if they exist
      if (node.children && node.children.length > 0) {
        const found = findResourceNode(
          node.children,
          parameterValue,
          parameterName,
        );
        if (found) return found;
      }
    }
    return undefined;
  };

  const showResourceNotFoundError = (parameterName: string): void => {
    if (parameterName === 'gapId') {
      notify?.error({
        message: t('GAP_NOT_FOUND_FOR_PLANT'),
        title: t('GAP_NOT_FOUND'),
      });
    } else {
      notify?.error({
        message: t('RESOURCE_NOT_FOUND_FOR_PLANT'),
        title: t('RESOURCE_NOT_FOUND'),
      });
    }
  };

  const showResourceNotAccessibleError = (parameterName: string): void => {
    if (parameterName === 'gapId') {
      notify?.error({
        message: t('GAP_NOT_ACCESSIBLE'),
        title: t('GAP_NOT_FOUND'),
      });
    } else {
      notify?.error({
        message: t('RESOURCE_NOT_ACCESSIBLE'),
        title: t('RESOURCE_NOT_FOUND'),
      });
    }
  };

  const selectNode = (node: TreeNodeType): void => {
    // Update user attributes for managed by
    try {
      const resourceDetails = findResourceDetails(
        rawData.value,
        node.value as string,
      );
      if (resourceDetails && resourceDetails.managedBy) {
        // Store managedBy in state if needed
      }
    } catch (detailsError) {
      console.error(
        '[useTreeSelector] Resource details lookup error:',
        detailsError,
      );
    }

    treeSelector.select(node);
  };

  const selectResourceNode = (resourceNode: TreeNodeType): void => {
    isSelectingFromRoute.value = true;
    try {
      selectedNode.value = resourceNode;
      selectNode(resourceNode);
    } catch (selectError) {
      console.error('[useTreeSelector] Node selection error:', selectError);
      throw selectError;
    } finally {
      isSelectingFromRoute.value = false;
    }
  };

  const handleRouteResourceSelection = async (
    parameterValue: string,
    parameterName: string,
  ): Promise<void> => {
    const resourceExists = checkResourceIdExists(
      rawData.value,
      parameterValue,
      parameterName,
    );

    if (!resourceExists) {
      console.warn(
        '[useTreeSelector] Resource not found in API data:',
        parameterValue,
      );
      showResourceNotFoundError(parameterName);
      await router.push(properties.basePath || '/epb-ui');
      return;
    }

    const resourceNode = findResourceNode(
      treeData.value,
      parameterValue,
      parameterName,
    );

    if (resourceNode) {
      selectResourceNode(resourceNode);
    } else {
      console.warn(
        '[useTreeSelector] Resource in API but not in tree:',
        parameterValue,
      );
      showResourceNotAccessibleError(parameterName);
      await router.push(properties.basePath || '/epb-ui');
    }
  };

  const handleAssignedResourceSelection = async (): Promise<void> => {
    const hasResourceAttribute = userStore.userAttributes?.some(
      (attribute) => attribute.userAttributeName === 'resource',
    );

    if (!hasResourceAttribute) {
      return;
    }

    const assignedResource = userStore.userAttributes.find(
      (attribute) => attribute.userAttributeName === 'resource',
    )?.value;

    if (typeof assignedResource !== 'string') {
      return;
    }

    try {
      const resourceExists = checkResourceIdExists(
        rawData.value,
        assignedResource,
      );
      if (!resourceExists) {
        return;
      }

      treeData.value = HierarchyService.filterTreeByResource(
        treeData.value,
        assignedResource,
      );

      const resourceNode = findResourceNode(treeData.value, assignedResource);
      if (resourceNode) {
        selectedNode.value = resourceNode;
        selectNode(resourceNode);
      }
    } catch (error) {
      console.error(
        '[useTreeSelector] Assigned resource selection failed:',
        error,
      );
    }
  };

  const handleInitialResourceSelection = async (): Promise<void> => {
    const parameterValue = route.params[
      properties.routeParamName || 'resourceId'
    ] as string;
    const parameterName = (route.meta?.paramName as string) || 'resourceId';

    if (parameterValue) {
      try {
        await handleRouteResourceSelection(parameterValue, parameterName);
      } catch (error) {
        console.error('[useTreeSelector] Resource selection error:', error);
        notify?.error({
          message: t('RESOURCE_SELECTION_ERROR'),
          title: t('ERROR'),
        });
        await router.push(properties.basePath || '/epb-ui');
      }
    } else {
      await handleAssignedResourceSelection();
    }
  };

  // Main functions
  const loadData = async (): Promise<void> => {
    if (!properties.apiFunction) {
      return;
    }

    try {
      isLoading.value = true;

      const response = await properties.apiFunction();

      if (Array.isArray(response)) {
        rawData.value = response;

        try {
          treeData.value = HierarchyService.transformApiToTree(response);
        } catch (transformError) {
          console.error(
            '[useTreeSelector] Tree transformation error:',
            transformError,
          );
          treeData.value = [];
          throw transformError;
        }
      } else {
        console.warn(
          '[useTreeSelector] API response is not an array:',
          typeof response,
        );
        rawData.value = [];
        treeData.value = [];
      }

      // Handle initial resource selection from URL or user permissions
      await handleInitialResourceSelection();
    } catch (error) {
      console.error('[useTreeSelector] Data loading error:', error);
    } finally {
      isLoading.value = false;
    }
  };

  const toggleNode = (nodeId: number | string): void => {
    if (expandedNodes.value.has(nodeId)) {
      expandedNodes.value.delete(nodeId);
    } else {
      expandedNodes.value.add(nodeId);
    }
  };

  const isNodeExpanded = (nodeId: number | string): boolean => {
    return expandedNodes.value.has(nodeId);
  };

  const expandAllNodes = (): void => {
    const expandNode = (nodes: Array<TreeNodeType>): void => {
      for (const node of nodes) {
        if (node.id) {
          expandedNodes.value.add(node.id);
        }
        if (node.children && node.children.length > 0) {
          expandNode(node.children);
        }
      }
    };
    expandNode(treeData.value);
  };

  const clearSearch = (): void => {
    searchQuery.value = '';
    expandedNodes.value.clear();
  };

  // Computed properties
  const filteredTreeData = computed(() => {
    return filterTreeNodes(treeData.value, searchQuery.value);
  });

  const displayText = computed(() => {
    // If a node is selected, show its label.
    // Only include gapId when the current route is the Live Status app.
    if (selectedNode.value) {
      const label =
        selectedNode.value.label || String(selectedNode.value.value || '');

      const isLiveStatusRoute =
        (route.meta as { appName?: string })?.appName ===
          'LIVE-STATUS-SCREEN' || route.path.includes('/live-status');

      if (isLiveStatusRoute) {
        // Prefer explicit gapDesc on node.meta, otherwise fall back to gapId
        const gapDescFromNode = selectedNode.value.meta?.gapDesc;
        const gapIdFromNode = selectedNode.value.meta?.gapId;
        const gapIdFromRoute =
          route.meta?.paramName === 'gapId'
            ? route.params[properties.routeParamName || 'resourceId']
            : undefined;
        let gapDesc: string | undefined;
        if (gapDescFromNode) {
          gapDesc = gapDescFromNode;
        } else if (gapIdFromNode) {
          gapDesc = String(gapIdFromNode);
        } else if (gapIdFromRoute) {
          gapDesc = String(gapIdFromRoute);
        }
        if (gapDesc) {
          return {
            resourceName: label,
            gapDesc,
          };
        }
      }

      return {
        resourceName: label,
      };
    }

    return {
      resourceName: 'Select from Plant tree',
    };
  });

  // Watch for route changes and trigger API calls
  watch(
    () => route.params[properties.routeParamName || 'resourceId'],
    async (newParameterValue, oldParameterValue) => {
      if (
        newParameterValue &&
        treeData.value.length > 0 &&
        typeof newParameterValue === 'string' &&
        newParameterValue !== oldParameterValue
      ) {
        isSelectingFromRoute.value = true;
        const parameterName = (route.meta?.paramName as string) || 'resourceId';

        try {
          // First validate if resource exists in raw API data
          const resourceExists = checkResourceIdExists(
            rawData.value,
            newParameterValue,
            parameterName,
          );
          if (!resourceExists) {
            console.warn(
              '[useTreeSelector] Route resource not found in API data:',
              newParameterValue,
            );

            // Show error message based on parameter type
            if (parameterName === 'gapId') {
              notify?.error({
                message: t('GAP_NOT_FOUND_FOR_PLANT'),
                title: t('GAP_NOT_FOUND'),
              });
            } else {
              notify?.error({
                message: t('RESOURCE_NOT_FOUND_FOR_PLANT'),
                title: t('RESOURCE_NOT_FOUND'),
              });
            }

            await router.push(properties.basePath || '/epb-ui');
            return;
          }

          // Check if resource is available in the current tree structure
          const resourceNode = findResourceNode(
            treeData.value,
            newParameterValue,
            parameterName,
          );
          if (resourceNode) {
            selectedNode.value = resourceNode;
            // Trigger hierarchy store update and API calls for route changes
            selectNode(resourceNode);
          } else {
            console.warn(
              '[useTreeSelector] Route resource in API but not in tree:',
              newParameterValue,
            );

            // Show error message based on parameter type
            if (parameterName === 'gapId') {
              notify?.error({
                message: t('GAP_NOT_ACCESSIBLE'),
                title: t('GAP_NOT_FOUND'),
              });
            } else {
              notify?.error({
                message: t('RESOURCE_NOT_ACCESSIBLE'),
                title: t('RESOURCE_NOT_FOUND'),
              });
            }

            await router.push(properties.basePath || '/epb-ui');
          }
        } catch (error) {
          console.error('[useTreeSelector] Route change error:', error);
          notify?.error({
            message: t('URL_PROCESSING_ERROR'),
            title: t('ERROR'),
          });
          await router.push(properties.basePath || '/epb-ui');
        } finally {
          isSelectingFromRoute.value = false;
        }
      } else if (!newParameterValue && oldParameterValue) {
        // ID was removed from URL - clear selection
        selectedNode.value = undefined;
      }
    },
  );

  // Watch for search query changes to auto-expand nodes when searching
  watch(searchQuery, (newQuery) => {
    if (newQuery.trim()) {
      expandAllNodes();
    }
  });

  return {
    clearSearch,
    displayText,
    filteredTreeData,
    isLoading,
    isNodeExpanded,
    loadData,
    searchQuery,
    selectNode,
    selectedNode,
    toggleNode,
    treeData,
  };
}

