/* =========================================================
 * HELPERS â snake_case â camelCase
 * (same philosophy as Management Control)
 * ========================================================= */

/**
 * Recursively converts all object keys from snake_case to camelCase.
 * @param key - Any JSON-like value.
 * @returns Value with all object keys camelCased.
 */
function toCamelCaseKey(key: string): string {
  const segments = key.split('_');
  if (segments.length <= 1) {
    return key;
  }

  const [first, ...rest] = segments;
  return (
    first +
    rest
      .map((segment) =>
        segment ? segment.charAt(0).toUpperCase() + segment.slice(1) : '',
      )
      .join('')
  );
}

/**
 * Recursively converts all object keys from snake_case to camelCase.
 * @param value - Any JSON-like value.
 * @returns Value with all object keys camelCased.
 */
function toCamelCaseDeep(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((it) => toCamelCaseDeep(it));
  }

  if (!value || typeof value !== 'object') {
    return value;
  }

  const record = value as Record<string, unknown>;
  const result: Record<string, unknown> = {};

  for (const [rawKey, rawValue] of Object.entries(record)) {
    result[toCamelCaseKey(rawKey)] = toCamelCaseDeep(rawValue);
  }

  return result;
}

/* =========================================================
 * NORMALIZER
 * ========================================================= */

/**
 * Recursively converts all object keys from snake_case to camelCase.
 * @param raw - Any JSON-like value.
 * @returns Value with all object keys camelCased.
 */
function normalizeAlertByWorkcentersResponse(
  raw: unknown,
): Array<AlertByWorkcentersDetailsResponseDto> {
  const camel = toCamelCaseDeep(raw);

  if (!Array.isArray(camel)) {
    return [];
  }

  return camel.filter(
    (item): item is AlertByWorkcentersDetailsResponseDto =>
      item !== null && typeof item === 'object',
  );
}

/* =========================================================
 * API â MAIN FUNCTION
 * ========================================================= */

export const getAlertByWorkcentersDetails = async (
  dto: GetAlertDetailForResourcesDto,
): Promise<Array<AlertByWorkcentersDetailsResponseDto>> => {
  const headers: Record<string, string> = {
    contentType: 'application/json',
  };

  if (token) {
    headers.authorization = `Bearer ${token}`;
  }

  const response: AxiosResponse<AlertByWorkcentersDetailsResponseDto> =
    await axios.post(
      `${edashboardBackendBaseUrl}/egap-board/alert-details-for-resources`,
      dto,
      { headers },
    );
  return normalizeAlertByWorkcentersResponse(response.data);
};

import axios, { AxiosResponse } from 'axios';
import type { ResourceMeta } from '@/global-components/TreeSelector/types';
import type {
  OptionalId,
  ApiResource,
  ApiWorkcenter,
  ApiProductionLine,
  ApiUap,
  ApiPlant,
} from '@/types/hierarchy.types';
import { Plant } from '@/types/plant';
import type { TreeNodeType } from '@/types/tree-select.types';
import appLogger from '@/utils/logger/app-logger';

export type { ApiPlant } from '@/types/hierarchy.types';
// ...existing code...

export class HierarchyService {
  public static transformApiToTree(
    apiData: Array<ApiPlant>,
  ): Array<TreeNodeType> {
    try {
      const result = apiData.map((plant, plantIndex) => {
        const plantNode: TreeNodeType = {
          id: plant.plantId ?? plantIndex,
          label: plant.plantDesc ?? `Plant ${plantIndex + 1}`,
          value: String(plant.plantId ?? plantIndex),
          children: this.transformUapsToTree(plant.uaps ?? [], plant.plantId),
        };

        return plantNode;
      });

      return result;
    } catch (error) {
      throw new Error(
        `Failed to transform API data to tree structure: ${error instanceof Error ? error.message : 'Unknown error'}`,
      );
    }
  }

  private static transformUapsToTree(
    uaps: Array<ApiUap>,
    plantId?: OptionalId,
  ): Array<TreeNodeType> {
    return uaps.map((uap, uapIndex) => ({
      children: this.transformProductionLinesToTree(
        uap.productionLines ?? [],
        plantId,
      ),
      id: uap.uapId ?? uapIndex,
      label: uap.uapDesc ?? '',
      value: String(uap.uapId ?? ''),
    }));
  }

  private static transformProductionLinesToTree(
    productionLines: Array<ApiProductionLine>,
    plantId?: OptionalId,
  ): Array<TreeNodeType> {
    return productionLines.map((productionLine, productionIndex) => ({
      id: productionLine.prodLineId ?? productionIndex,
      label: productionLine.prodLineDesc ?? '',
      value: String(productionLine.prodLineId ?? ''),
      children: this.transformWorkcentersToTree(
        productionLine.workcenters ?? [],
        plantId,
      ),
    }));
  }

  private static transformWorkcentersToTree(
    workcenters: Array<ApiWorkcenter>,
    plantId?: OptionalId,
  ): Array<TreeNodeType> {
    return workcenters.map((wc, wcIndex) => ({
      children: this.transformResourcesToTree(wc.resources ?? [], plantId),
      id: wc.workcenterId ?? wcIndex,
      label: wc.workcenterDesc ?? '',
      value: String(wc.workcenterId ?? ''),
    }));
  }

  private static transformResourcesToTree(
    resources: Array<ApiResource>,
    plantId?: OptionalId,
  ): Array<TreeNodeType> {
    try {
      const result = resources.map((resource, resourceIndex) => {
        // Ensure we have a valid resourceId, use fallback if needed
        const resourceId = resource.resourceId ?? `resource_${resourceIndex}`;
        const resourceName =
          resource.resourceName ??
          String(resource.resourceId ?? `Resource ${resourceIndex + 1}`);

        const resourceNode: TreeNodeType = {
          id: resourceId,
          label: resourceName,
          value: String(resourceId),
          meta: {
            gapDesc: resource.gapDesc,
            gapId: resource.gapId,
            plantId: resource.plantId ?? plantId, // Use resource-specific plantId if available, otherwise inherit from parent plant
            productionLineId: resource.productionLineId,
            resourceId,
            uapId: resource.uapId,
            workcenterId: resource.workcenterId,
          } as ResourceMeta,
        };

        return resourceNode;
      });

      return result;
    } catch (error) {
      appLogger.error(
        '[HierarchyService] Error transforming resources:',
        String(error),
      );
      throw new Error(
        `Failed to transform resources: ${error instanceof Error ? error.message : 'Unknown error'}`,
      );
    }
  }

  public static filterTreeByResource(
    nodes: Array<TreeNodeType>,
    resourceId: string,
  ): Array<TreeNodeType> {
    return nodes
      .map((node) => {
        if (node.children && node.children.length > 0) {
          const filteredChildren = this.filterTreeByResource(
            node.children,
            resourceId,
          );
          if (filteredChildren.length > 0) {
            return { ...node, children: filteredChildren };
          }
          return;
        }
        // Check if this is a resource node matching the resourceId
        if (!node.children && node.value === resourceId) {
          return node;
        }
      })
      .filter((node): node is TreeNodeType => node !== undefined);
  }

  public static findNodePath(
    nodes: Array<TreeNodeType>,
    targetValue: string,
  ): unknown {
    for (const node of nodes) {
      if (node.value === targetValue && !node.children) {
        return { resource: node.label };
      }
      if (node.children && node.children.length > 0) {
        const childPath = this.findNodePath(node.children, targetValue);
        if (childPath) {
          return {
            [this.getNodeLevel(node)]: node.label,
            ...childPath,
          };
        }
      }
    }
    return undefined;
  }

  private static getNodeLevel(node: TreeNodeType): string {
    // Determine the level based on node structure
    // This is a simplified version - you might need more sophisticated logic
    if (
      node.children?.some((child) =>
        child.children?.some((gc) => gc.children?.some((ggc) => !ggc.children)),
      )
    ) {
      return 'plant';
    }
    if (
      node.children?.some((child) => child.children?.some((gc) => !gc.children))
    ) {
      return 'uap';
    }
    if (node.children?.some((child) => !child.children)) {
      return 'productionLine';
    }
    if (node.children && node.children.length > 0) {
      return 'workcenter';
    }
    return 'resource';
  }

  public static findResourceByGapId(
    apiData: Array<ApiPlant>,
    gapId: string,
  ): { resourceId: string; resourceNode: TreeNodeType } | undefined {
    for (const plant of apiData) {
      const result = this.searchGapIdInPlant(plant, gapId);
      if (result) {
        return result;
      }
    }
    return undefined;
  }

  private static searchGapIdInPlant(
    plant: ApiPlant,
    gapId: string,
  ): { resourceId: string; resourceNode: TreeNodeType } | undefined {
    if (!plant.uaps) {
      return undefined;
    }

    for (const uap of plant.uaps) {
      const result = this.searchGapIdInUap(uap, plant.plantId, gapId);
      if (result) {
        return result;
      }
    }
    return undefined;
  }

  private static searchGapIdInUap(
    uap: ApiUap,
    plantId: OptionalId,
    gapId: string,
  ): { resourceId: string; resourceNode: TreeNodeType } | undefined {
    if (!uap.productionLines) {
      return undefined;
    }

    for (const productionLine of uap.productionLines) {
      const result = this.searchGapIdInProductionLine(
        productionLine,
        plantId,
        uap.uapId,
        gapId,
      );
      if (result) {
        return result;
      }
    }
    return undefined;
  }

  private static searchGapIdInProductionLine(
    productionLine: ApiProductionLine,
    plantId: OptionalId,
    uapId: OptionalId,
    gapId: string,
  ): { resourceId: string; resourceNode: TreeNodeType } | undefined {
    if (!productionLine.workcenters) {
      return undefined;
    }

    for (const wc of productionLine.workcenters) {
      const result = this.searchGapIdInWorkcenter(
        wc,
        plantId,
        uapId,
        productionLine.prodLineId,
        gapId,
      );
      if (result) {
        return result;
      }
    }
    return undefined;
  }

  private static searchGapIdInWorkcenter(
    wc: ApiWorkcenter,
    plantId: OptionalId,
    uapId: OptionalId,
    productionLineId: OptionalId,
    gapId: string,
  ): { resourceId: string; resourceNode: TreeNodeType } | undefined {
    if (!wc.resources) {
      return undefined;
    }

    for (const resource of wc.resources) {
      if (resource.gapId === gapId) {
        return this.createResourceResult(
          resource,
          plantId,
          uapId,
          productionLineId,
          wc.workcenterId,
        );
      }
    }
    return undefined;
  }

  private static createResourceResult(
    resource: ApiResource,
    plantId: OptionalId,
    uapId: OptionalId,
    productionLineId: OptionalId,
    workcenterId: OptionalId,
  ): { resourceId: string; resourceNode: TreeNodeType } {
    const resourceNode: TreeNodeType = {
      id: resource.resourceId ?? '',
      label: resource.resourceName ?? '',
      value: String(resource.resourceId ?? ''),
      meta: {
        gapDesc: resource.gapDesc,
        gapId: resource.gapId,
        plantId,
        productionLineId,
        resourceId: resource.resourceId,
        uapId,
        workcenterId,
      } as ResourceMeta,
    };
    return {
      resourceId: String(resource.resourceId),
      resourceNode,
    };
  }

  private readonly baseUrl: string;

  private readonly token: string;

  public getHierarchy = async (): Promise<Array<Plant>> => {
    const userId = localStorage.getItem('userId');
    const response: AxiosResponse = await axios.get(
      `${this.baseUrl}/epart-board/getHierarchy/${userId}`,
      { headers: { authorization: `Bearer ${this.token}` } },
    );
    return response.data;
  };

  public constructor(baseUrl: string, authToken?: string) {
    this.baseUrl = baseUrl;
    this.token = authToken || '';
  }
}

import type {
  CheckpointResult,
  GetManagementControlQuery,
  ManagementControlApiResponse,
  ManagementControlCheckpoint,
} from '@/types/management-control-api.types';
import type {
  ControlIndicatorStatus,
  ManagementControlCard,
} from '@/types/management-control.types';

const token = import.meta.env.TOKEN;
const edashboardBackendBaseUrl = import.meta.env.EPART_BOARD_BACKEND_URL;

/**
 * Converts a snake_case key to camelCase.
 * @param key - Key name to convert.
 * @returns camelCased key.
 */
function toCamelCaseKey(key: string): string {
  const segments = key.split('_');
  if (segments.length <= 1) {
    return key;
  }

  const [first, ...rest] = segments;
  return (
    first +
    rest
      .map((segment) => {
        if (!segment) {
          return '';
        }
        return segment.charAt(0).toUpperCase() + segment.slice(1);
      })
      .join('')
  );
}

/**
 * Recursively converts all object keys from snake_case to camelCase.
 * @param value - Any JSON-like value.
 * @returns Value with all object keys camelCased.
 */
function toCamelCaseDeep(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((it) => toCamelCaseDeep(it));
  }
  if (!value || typeof value !== 'object') {
    return value;
  }

  const record = value as Record<string, unknown>;
  const result: Record<string, unknown> = {};
  for (const [rawKey, rawValue] of Object.entries(record)) {
    result[toCamelCaseKey(rawKey)] = toCamelCaseDeep(rawValue);
  }
  return result;
}

/**
 * Processes checkpoint results array from raw data.
 * @param resultsRaw - Raw checkpoint results data.
 * @returns Array of processed checkpoint results.
 */
function processCheckpointResults(
  resultsRaw: unknown,
): Array<CheckpointResult> {
  if (!Array.isArray(resultsRaw)) {
    return [];
  }

  const results: Array<CheckpointResult> = [];
  for (const resultItem of resultsRaw) {
    if (resultItem && typeof resultItem === 'object') {
      const { label, status } = resultItem as {
        label?: unknown;
        status?: unknown;
      };

      if (typeof label === 'string' && typeof status === 'string') {
        results.push({
          label,
          status: status as CheckpointResult['status'],
        });
      }
    }
  }

  return results;
}

/**
 * Processes a single management control item from raw data.
 * @param record - Raw record data.
 * @returns Processed management control checkpoint or null if invalid.
 */
function processManagementControlItem(
  record: Record<string, unknown>,
): ManagementControlCheckpoint | undefined {
  const idRaw = record.id;
  const id = typeof idRaw === 'number' ? idRaw : Number(idRaw);

  if (!Number.isFinite(id)) {
    return undefined;
  }

  const results = processCheckpointResults(record.checkpointResults);
  const labelIsDashOrOk = Boolean(
    record.labelIsDashOrOk ?? record.labelIsDashorOK,
  );

  return {
    checkpointCategoryColor:
      typeof record.checkpointCategoryColor === 'string'
        ? record.checkpointCategoryColor
        : '',
    checkpointCategoryDescription:
      typeof record.checkpointCategoryDescription === 'string'
        ? record.checkpointCategoryDescription
        : '',
    checkpointDescription:
      typeof record.checkpointDescription === 'string'
        ? record.checkpointDescription
        : '',
    checkpointResults: results,
    id,
    labelIsDashOrOk,
  };
}

/**
 * Normalizes backend response (snake_case) to camelCase DTO.
 * @param raw - Raw response payload from backend.
 * @returns Normalized management control API response.
 */
function normalizeManagementControlApiResponse(
  raw: unknown,
): ManagementControlApiResponse {
  const camel = toCamelCaseDeep(raw);
  if (!Array.isArray(camel)) {
    return [];
  }

  const normalized: Array<ManagementControlCheckpoint> = [];

  for (const item of camel) {
    if (item && typeof item === 'object') {
      const record = item as Record<string, unknown>;
      const processed = processManagementControlItem(record);

      if (processed) {
        normalized.push(processed);
      }
    }
  }

  return normalized;
}

/**
 * Fetches management control details from the API.
 * @param query - The query parameters for fetching management control data.
 * @returns Promise resolving to management control API response.
 */
export async function fetchManagementControlDetails(
  query: GetManagementControlQuery,
): Promise<ManagementControlApiResponse> {
  const parameters = new URLSearchParams({
    plant: query.plant,
    shiftEndDate: query.shiftEndDate,
    shiftStartDate: query.shiftStartDate,
    team: query.team,
    ...(query.timezone ? { timezone: query.timezone } : {}),
  });

  const url = `${edashboardBackendBaseUrl}/egap-board/management-control-details?${parameters.toString()}`;

  const headers = new Headers();
  headers.set('Content-Type', 'application/json');
  if (token) {
    headers.set('authorization', `Bearer ${token}`);
  }

  const response = await fetch(url, {
    credentials: 'include',
    headers,
    method: 'GET',
  });

  if (!response.ok) {
    throw new Error(
      `Failed to fetch management control details: ${response.statusText}`,
    );
  }

  let rawData: unknown;
  if (response.status !== 204) {
    try {
      rawData = await response.json();
    } catch {
      rawData = undefined;
    }
  }

  return normalizeManagementControlApiResponse(rawData);
}

/**
 * Maps API status string to control indicator status.
 * @param apiStatus - The status string from the API (green, red, gray).
 * @returns The corresponding control indicator status.
 */
function mapApiStatusToIndicatorStatus(
  apiStatus: string,
): ControlIndicatorStatus {
  switch (apiStatus.toLowerCase()) {
    case 'green': {
      return 'valid';
    }
    case 'red': {
      return 'invalid';
    }
    case 'gray':
    case 'grey': {
      return 'pending';
    }
    default: {
      return 'na';
    }
  }
}

/**
 * Transforms API response to management control card format.
 * @param apiResponse - The raw API response data.
 * @returns Array of management control cards.
 */
export function transformApiResponseToCards(
  apiResponse: ManagementControlApiResponse,
): Array<ManagementControlCard> {
  return apiResponse.map((checkpoint) => ({
    category: checkpoint.checkpointCategoryDescription?.trim() || 'Other',
    categoryIconColor: checkpoint.checkpointCategoryColor,
    categoryLabel: checkpoint.checkpointCategoryDescription?.trim() || 'Other',
    id: String(checkpoint.id),
    indicators: checkpoint.checkpointResults.map((result) => ({
      label: result.label,
      status: mapApiStatusToIndicatorStatus(result.status),
    })),
    title: checkpoint.checkpointDescription,
  }));
}

