/**
 * Converts a snake_case key to camelCase.
 * @param key - Key name to convert.
 * @returns camelCased key.
 */
function toCamelCaseKey(key: string): string {
  const segments = key.split('_');
  if (segments.length <= 1) {
    return key;
  }

  const [first, ...rest] = segments;
  return (
    first +
    rest
      .map((segment) => {
        if (!segment) {
          return '';
        }
        return segment.charAt(0).toUpperCase() + segment.slice(1);
      })
      .join('')
  );
}

/**
 * Recursively converts all object keys from snake_case to camelCase.
 * @param value - Any JSON-like value.
 * @returns Value with all object keys camelCased.
 */
function toCamelCaseDeep(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((it) => toCamelCaseDeep(it));
  }
  if (!value || typeof value !== 'object') {
    return value;
  }

  const record = value as Record<string, unknown>;
  const result: Record<string, unknown> = {};
  for (const [rawKey, rawValue] of Object.entries(record)) {
    result[toCamelCaseKey(rawKey)] = toCamelCaseDeep(rawValue);
  }
  return result;
}

/**
 * Processes a single ok first part detail item from raw data.
 * @param record - Raw record data.
 * @returns Processed ok first part detail item or undefined if invalid.
 */
function processOkFirstPartDetailItem(
  record: Record<string, unknown>,
): OkFirstPartDetailItem | undefined {
  const idRaw = record.id;
  const id = typeof idRaw === 'number' ? idRaw : Number(idRaw);

  if (!Number.isFinite(id)) {
    return undefined;
  }

  const creationDate =
    typeof record.creationDate === 'string' ? record.creationDate : '';
  let closedDate: string | undefined;
  if (record.closedDate === null) {
    closedDate = undefined;
  } else if (typeof record.closedDate === 'string') {
    closedDate = record.closedDate;
  } else {
    closedDate = undefined;
  }
  const duration = typeof record.duration === 'string' ? record.duration : '';
  const subPerimeter =
    typeof record.subPerimeter === 'number'
      ? record.subPerimeter
      : Number(record.subPerimeter) || 0;
  const subPerimeterDescription =
    typeof record.subPerimeterDescription === 'string'
      ? record.subPerimeterDescription
      : '';
  const color =
    record.color === 'green' || record.color === 'red' ? record.color : 'red';

  return {
    closedDate,
    color,
    creationDate,
    duration,
    id,
    subPerimeter,
    subPerimeterDescription,
  };
}

/**
 * Normalizes backend response (snake_case) to camelCase DTO.
 * @param raw - Raw response payload from backend.
 * @returns Normalized ok first part details API response.
 */
function normalizeOkFirstPartDetailsApiResponse(
  raw: unknown,
): OkFirstPartDetailsApiResponse {
  const camel = toCamelCaseDeep(raw);
  if (!Array.isArray(camel)) {
    return [];
  }

  const normalized: Array<OkFirstPartDetailItem> = [];

  for (const item of camel) {
    if (item && typeof item === 'object') {
      const record = item as Record<string, unknown>;
      const processed = processOkFirstPartDetailItem(record);

      if (processed) {
        normalized.push(processed);
      }
    }
  }

  return normalized;
}

