/**
 * Creates standard headers for API requests.
 * @returns Headers object with Content-Type and Authorization (if token is available)
 */
function createHeaders(): Headers {
  const headers = new Headers();
  headers.set('Content-Type', 'application/json');
  if (token) {
    headers.set('Authorization', `Bearer ${token}`);
  }
  return headers;
}

/**
 * Builds URL with query parameters.
 * @param path - API endpoint path
 * @param parameters - Optional query parameters as key-value pairs
 * @returns Full URL string with query parameters appended
 */
function buildUrl(path: string, parameters?: Record<string, unknown>): string {
  // Ensure base URL ends with / so relative paths append correctly
  const baseUrl = adminBackendBaseUrl.endsWith('/')
    ? adminBackendBaseUrl
    : `${adminBackendBaseUrl}/`;
  const url = new URL(path, baseUrl);

  if (parameters) {
    for (const [key, value] of Object.entries(parameters)) {
      // Only convert primitives to strings; skip objects and arrays
      if (
        value !== undefined &&
        value !== null &&
        (typeof value === 'string' ||
          typeof value === 'number' ||
          typeof value === 'boolean')
      ) {
        url.searchParams.set(key, String(value));
      }
    }
  }

  return url.toString();
}

/**
 * Normalizes a single part of a component code.
 * @param part Single part of the code to normalize
 * @returns Normalized part in camelCase
 */
const normalizePart = (part: string): string => {
  let result = part;

  // Insert marker before uppercase that follows lowercase/digit
  result = result.replace(/([\da-z])([A-Z])/g, '$1_$2');

  // Insert marker before last uppercase in consecutive capitals
  // (handles acronyms like "KPISection" â "KPI_Section")
  result = result.replace(/([A-Z])([A-Z][a-z])/g, '$1_$2');

  const parts = result.split('_');
  return (
    parts[0].toLowerCase() +
    parts
      .slice(1)
      .map(
        (piece: string) =>
          piece.charAt(0).toUpperCase() + piece.slice(1).toLowerCase(),
      )
      .join('')
  );
};

/**
 * Normalizes component codes from PascalCase/snake_case to camelCase.
 * This ensures API responses with different naming conventions work with the renderer registry.
 * @param code Component code from JSON config
 * @returns Normalized camelCase code
 */
function normalizeComponentCode(code: string): string {
  const trimmed = code.trim();
  if (!trimmed) return code;

  const parts = trimmed
    .split('_')
    .filter(Boolean)
    .map((part) => normalizePart(part));
  if (parts.length === 0) return '';

  return (
    parts[0] +
    parts
      .slice(1)
      .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
      .join('')
  );
}

/**
 * Recursively normalizes component codes in layout sections and widgets.
 * @param layout Layout document to normalize
 */
function normalizeLayoutComponentCodes(layout: PageLayoutDocument): void {
  if (!layout.devices) return;

  interface Widget {
    component?: { code: string };
    components?: Array<Widget>;
  }

  interface Section {
    widgets?: Array<Widget>;
  }

  interface Device {
    layout?: { sections: Array<Section> };
  }

  const normalizeWidget = (widget: Widget): void => {
    const normalizedWidget = widget;
    if (normalizedWidget?.component?.code) {
      normalizedWidget.component.code = normalizeComponentCode(
        normalizedWidget.component.code,
      );
    }
    if (Array.isArray(normalizedWidget?.components)) {
      for (const child of normalizedWidget.components) {
        normalizeWidget(child);
      }
    }
  };

  const normalizeSections = (sections: Array<Section>): void => {
    for (const section of sections) {
      if (Array.isArray(section?.widgets)) {
        for (const widget of section.widgets) {
          normalizeWidget(widget);
        }
      }
    }
  };

  for (const device of Object.values(layout.devices)) {
    const typedDevice = device as Device;
    if (typedDevice?.layout?.sections) {
      normalizeSections(typedDevice.layout.sections);
    }
  }
}

/**
 * Parses and validates the layout response body.
 * @param text - Raw response text
 * @returns Parsed layout document
 */
function parseLayoutResponse(text: string): PageLayoutDocument {
  if (!text) {
    throw new Error('API returned empty response body');
  }

  const fullResponse = JSON.parse(text);

  // Verify the layout structure exists in the response
  const layout = fullResponse.devices?.desktop?.layout;

  if (!layout) {
    console.error(
      '[DEBUG] Layout not found. Response structure:',
      fullResponse,
    );
    throw new Error('Layout not found in response structure');
  }

  // Normalize all component codes to match renderer registry
  normalizeLayoutComponentCodes(fullResponse);

  return fullResponse as PageLayoutDocument;
}

