/**
 * Converts a snake_case key to camelCase.
 * @param key - Key name to convert.
 * @returns camelCased key.
 */
function toCamelCaseKey(key: string): string {
  const segments = key.split('_');
  if (segments.length <= 1) {
    return key;
  }

  const [first, ...rest] = segments;
  return (
    first +
    rest
      .map((segment) => {
        if (!segment) {
          return '';
        }
        return segment.charAt(0).toUpperCase() + segment.slice(1);
      })
      .join('')
  );
}

/**
 * Recursively converts all object keys from snake_case to camelCase.
 * @param value - Any JSON-like value.
 * @returns Value with all object keys camelCased.
 */
function toCamelCaseDeep(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((it) => toCamelCaseDeep(it));
  }
  if (!value || typeof value !== 'object') {
    return value;
  }

  const record = value as Record<string, unknown>;
  const result: Record<string, unknown> = {};
  for (const [rawKey, rawValue] of Object.entries(record)) {
    result[toCamelCaseKey(rawKey)] = toCamelCaseDeep(rawValue);
  }
