}

/**
 * Processes a single routine detail item from raw data.
 * @param record - Raw record data.
 * @returns Processed routine detail item or undefined if invalid.
 */
function processRoutineDetailItem(
  record: Record<string, unknown>,
): RoutineDetailItem | undefined {
  const scheduleEntryIdRaw = record.scheduleEntryId;
  const scheduleEntryId =
    typeof scheduleEntryIdRaw === 'number'
      ? scheduleEntryIdRaw
      : Number(scheduleEntryIdRaw);

  const scheduleIdRaw = record.scheduleId;
  const scheduleId =
    typeof scheduleIdRaw === 'number' ? scheduleIdRaw : Number(scheduleIdRaw);

  if (!Number.isFinite(scheduleEntryId) || !Number.isFinite(scheduleId)) {
    return undefined;
  }

  const description =
    typeof record.description === 'string' ? record.description : '';
  const statusValue =
    typeof record.status === 'string' ? record.status.toUpperCase() : '';
  const status =
    statusValue === 'OK' || statusValue === 'NOK' || statusValue === 'NA'
      ? statusValue
      : 'NOK';
  const color =
    record.color === 'green' ||
    record.color === 'red' ||
    record.color === 'gray' ||
    record.color === 'grey'
      ? record.color
      : statusValue === 'NA'
        ? 'gray'
        : 'red';
  return {
    color,
    description,
    scheduleEntryId,
    scheduleId,
    status,
  };
}

/**
 * Normalizes backend response (snake_case) to camelCase DTO.
