  }

  let rawData: unknown;
  if (response.status !== 204) {
    try {
      rawData = await response.json();
    } catch {
      rawData = undefined;
    }
  }

  return normalizeRoutineDetailsApiResponse(rawData);
}

/**
 * Maps API status string to routine status.
 * @param apiStatus - The status string from the API (OK, NOK).
 * @returns The corresponding routine status.
 */
function mapApiStatusToRoutineStatus(apiStatus: string): RoutineStatus {
  switch (apiStatus.toUpperCase()) {
    case 'OK': {
      return 'ok';
    }
    case 'NOK': {
      return 'nok';
    }
    case 'NA': {
      return 'na';
    }
    default: {
      return 'pending';
    }
  }
}

/**
 * Transforms API response to routine card format.
 * @param apiResponse - The raw API response data.
 * @returns Array of routine cards.
 */
export function transformApiResponseToRoutineCards(
  apiResponse: RoutineDetailsApiResponse,
): Array<RoutineCard> {
  return apiResponse.map((item) => ({
    color: item.color,
    description: item.description,
    id: `${item.scheduleEntryId}-${item.scheduleId}`,
    scheduleEntryId: item.scheduleEntryId,
    scheduleId: item.scheduleId,
    status: mapApiStatusToRoutineStatus(item.status),
  }));
}

