/**
 * Format time from ISO string to HH:MM
 * @param datetime - ISO date string to format
 * @returns Formatted time string in HH:MM
 */
export const formatShiftTime = (datetime: string): string =>
  datetime
    ? new Date(datetime).toLocaleTimeString('fr-FR', {
        hour: '2-digit',
        minute: '2-digit',
      })
    : '';

/**
 * Format shift label with shift number and start time
 * @param shift - Shift number
 * @param start - ISO start time string
 * @returns Formatted shift label string
 */
export const formatShiftLabel = (shift: number, start: string): string =>
  `Shift ${shift} (${formatShiftTime(start)})`;

const STATUS_TYPES = ['prod', 'op', 'ps', 'co', 'ls', 'qu', 'uc'];
const STATUS_COLORS: Record<string, string> = {
  co: '#00bcd4',
  ls: '#f44336',
  op: '#9c27b0',
  prod: '#4caf50',
  ps: '#607d8b',
  qu: '#ff9800',
  uc: '#9e9e9e',
};

/**
 *
 * @param token
 */
function getSpeedAlignmentClasses(token: string): string {
  const normalized = token.trim().toUpperCase();

  if (!normalized) {
    return '';
  }

  if (normalized === 'NA') {
    return 'speed-center';
  }

  const [mode] = normalized.split('|');

  switch (mode) {
    case '-1': {
      return 'speed-left';
    }
    case '0': {
      return 'speed-center';
    }
    case '1': {
      return 'speed-right';
    }
    default: {
      return 'speed-center';
    }
  }
}

/**
 *
 * @param token
 * @param index
 * @param rowHour
 * @param currentHour
 * @param currentMinute
 */
function getStatusSegment(
  token: string,
  index: number,
  rowHour: number,
  currentHour: number,
  currentMinute: number,
): SegmentData {
  const trimmed = token.trim();
  const isCurrentHour = rowHour === currentHour;
  const currentSlotIndex = Math.floor(currentMinute / 5);

  if (trimmed === '') {
    if (rowHour < currentHour) {
      return { value: -1, type: 'prod', color: STATUS_COLORS.prod };
    }

    if (isCurrentHour) {
      if (currentSlotIndex === 0 && currentMinute < 5) {
        return { value: -1, type: 'empty', color: 'transparent' };
      }

      if (index <= currentSlotIndex) {
        return { value: -1, type: 'prod', color: STATUS_COLORS.prod };
      }
    }

    return { value: -1, type: 'empty', color: 'transparent' };
  }

  if (trimmed.toUpperCase() === 'NA') {
    return {
      value: 0,
      type: 'prod',
      color: STATUS_COLORS.prod,
    };
  }

  const slotNumber = Number.parseInt(trimmed, 10);
  const type = STATUS_TYPES[slotNumber] || 'prod';

  return {
    value: slotNumber,
    type,
    color: STATUS_COLORS[type] || STATUS_COLORS.uc,
  };
}

/**
 * Format shift production data for UI display
 * @param rows - Array of shift production items
 * @returns Array of formatted production items for UI
 */
export const formatShiftProductionDataForUI = (
  rows: Array<ShiftProductionItem> | undefined,
): Array<FormattedProductionItem> => {
  if (!rows) {
    return [];
  }

  return rows.map((it) => {
    const delta = it.prod - it.target;
    const causeNumber = 0;

    const now = new Date();
    const rowHour = Number.parseInt(it.hour.split(':')[0], 10);
    const currentHour = now.getHours();
    const currentMinute = now.getMinutes();
    const isSpeedMode = it.slotMode === 'SPEED';
    const slotSource = it.slot ?? '';
    const speedSource = it.speed ?? '';
    const statusTokens = slotSource.split(';');
    const speedTokens = speedSource.split(';');
    const slotSegments = statusTokens.map((slotValue, index) => {
      const baseSegment = getStatusSegment(
        slotValue,
        index,
        rowHour,
        currentHour,
        currentMinute,
      );

      if (!isSpeedMode) {
        return baseSegment;
      }

      const alignmentClasses = getSpeedAlignmentClasses(
        speedTokens[index] ?? '',
      );

      return {
        ...baseSegment,
        type: alignmentClasses
          ? `${baseSegment.type} ${alignmentClasses}`
          : baseSegment.type,
      };
    });

    let referenceIcon;
    switch (it.ref.type) {
      case 'workorder': {
        referenceIcon = 'work';
        break;
      }
      case 'batch': {
        referenceIcon = 'inventory';
        break;
      }
      case 'sebango': {
        referenceIcon = 'qr_code';
        break;
      }
      default: {
        referenceIcon = 'description';
      }
    }

    let causeColor;
    switch (it.cause) {
      case 'green': {
        causeColor = '#28a745';
        break;
      }
      case 'yellow': {
        causeColor = '#ffc107';
        break;
      }
      case 'red': {
        causeColor = '#dc3545';
        break;
      }
      default: {
        causeColor = '#6c757d';
      }
    }

    return {
      tool: it.tool,
      cause: it.cause,
      causeColor,
      causeNumber,
      comments: it.comments,
      delta,
      deltaColor: delta >= 0 ? '#28a745' : '#dc3545',
      deltaFormatted: delta >= 0 ? `+${delta}` : `${delta}`,
      description: it.description,
      hour: it.hour,
      mostRecentTicket: it.mostRecentTicket,
      prod: it.prod,
      ref: it.ref.value,
      refIcon: referenceIcon,
      slotOriginal: isSpeedMode ? speedSource : slotSource,
      slotSegments,
      slowdown: it.slowdown,
      target: it.target,
      tickets: it.tickets,
      ucTicket: it.ucTicket,
    };
  });
};

/**
 * Format shift context data for UI display
 * @param data - Shift API data object
 * @returns Record of formatted shift info objects
 */
export const formatShiftDataForUI = (
  data: ShiftApiData | undefined,
): Record<string, FormattedShiftInfo> => {
  const current = data?.currentShift;
  const previous = data?.previousShift;
  const previousPrevious = data?.previousPreviousShift;

  return {
    currentShift: current
      ? {
          endTime: formatShiftTime(current.endDatetime),
          id: 'current-shift-btn',
          isActive: true,
          label: formatShiftLabel(current.shift, current.startDatetime),
          shift: current.shift,
          startTime: formatShiftTime(current.startDatetime),
        }
      : {
          endTime: '',
          id: 'current-shift-btn',
          isActive: true,
          label: '',
          shift: 0,
          startTime: '',
        },
    previousShift: previous
      ? {
          endTime: formatShiftTime(previous.endDatetime),
          id: 'previous-shift-btn',
          isActive: false,
          label: formatShiftLabel(previous.shift, previous.startDatetime),
          shift: previous.shift,
          startTime: formatShiftTime(previous.startDatetime),
        }
      : {
          endTime: '',
          id: 'previous-shift-btn',
          isActive: false,
          label: '',
          shift: 0,
          startTime: '',
        },
    previousPreviousShift: previousPrevious
      ? {
          endTime: formatShiftTime(previousPrevious.endDatetime),
          id: 'pprevious-shift-btn',
          isActive: false,
          label: formatShiftLabel(
            previousPrevious.shift,
            previousPrevious.startDatetime,
          ),
          shift: previousPrevious.shift,
          startTime: formatShiftTime(previousPrevious.startDatetime),
        }
      : {
          endTime: '',
          id: 'pprevious-shift-btn',
          isActive: false,
          label: '',
          shift: 0,
          startTime: '',
        },
  };
};

import axios from 'axios';

const token = import.meta.env.TOKEN;
const edashboardBackendBaseUrl = import.meta.env.EPART_BOARD_BACKEND_URL;

export interface TeamOption {
  label: string;
  teamId: string;
  teamName: string;
  searchText: string;
  value: string;
}

/**
 * Adds a team entry to the teams map from a raw value (string, number, or object).
 * @param teamsMap - The map to populate with team options.
 * @param teamLike - Raw team data from the API (string, number, or object with id/name).
 */
function addTeamOption(
  teamsMap: Map<string, TeamOption>,
  teamLike: unknown,
): void {
  if (!teamLike) {
    return;
  }

  if (typeof teamLike === 'string' || typeof teamLike === 'number') {
    const value = String(teamLike).trim();
    if (value) {
      teamsMap.set(value, {
        label: `ID - ${value}`,
        searchText: `id ${value}`.toLowerCase(),
        teamId: value,
        teamName: '',
        value,
      });
    }
    return;
  }

  if (typeof teamLike === 'object') {
    const record = teamLike as Record<string, unknown>;
    const rawValue = record.id;
    const rawName = record.name;

    const value =
      typeof rawValue === 'string' || typeof rawValue === 'number'
        ? String(rawValue).trim()
        : '';
    const name =
      typeof rawName === 'string' || typeof rawName === 'number'
        ? String(rawName).trim()
        : '';

    if (value) {
      teamsMap.set(value, {
        label: `ID. Team ${value}`,
        searchText: `id ${value} ${name}`.toLowerCase(),
        teamId: value,
        teamName: name,
        value,
      });
    }
  }
}

/**
 * Fetches and parses the team list for a given plant from the backend.
 * @param plant - The plant identifier.
 * @returns Sorted array of team options.
 */
async function extractTeamOptionsFromPlant(
  plant: string,
): Promise<Array<TeamOption>> {
  if (!plant?.trim()) {
    return [];
  }

  const headers: Record<string, string> = {};
  headers['Content-Type'] = 'application/json';
  if (token) {
    headers.authorization = `Bearer ${token}`;
  }

  let raw: unknown;
  try {
    const response = await axios.get(
      `${edashboardBackendBaseUrl}/egap-board/team-list/${encodeURIComponent(plant)}`,
      {
        headers,
        withCredentials: true,
      },
    );
    raw = response.data as unknown;
  } catch (error_) {
    const statusText =
      axios.isAxiosError(error_) && error_.response?.statusText
        ? error_.response.statusText
        : 'Request failed';
    throw new Error(`Failed to fetch teams: ${statusText}`);
  }

  const teamsMap = new Map<string, TeamOption>();

  if (Array.isArray(raw)) {
    for (const teamLike of raw) {
      addTeamOption(teamsMap, teamLike);
    }
  }

  return [...teamsMap.values()].sort((first, second) =>
    first.label.localeCompare(second.label),
  );
}

/**
 * Fetches the list of available teams for a given plant.
 * @param plant - The plant identifier.
 * @returns Promise resolving to an array of team options.
 */
export async function fetchTeams(plant: string): Promise<Array<TeamOption>> {
  if (!plant?.trim()) {
    return [];
  }

  return extractTeamOptionsFromPlant(plant);
}

import type {
  GetTpmDetailsQuery,
  TpmDetailItem,
  TpmDetailColor,
  TpmDetailStatus,
  TpmDetailsResponse,
} from '@/types/tpm-details.types';

const token = import.meta.env.TOKEN;
const edashboardBackendBaseUrl = import.meta.env.EPART_BOARD_BACKEND_URL;

/**
 * Normalizes a raw status value from the backend into a {@link TpmDetailStatus}.
 * @param raw - Raw status value (e.g. string/boolean/number) to normalize.
 * @returns The normalized status value.
 */
function normalizeStatus(raw: unknown): TpmDetailStatus {
  if (typeof raw === 'string') {
    const value = raw.trim().toLowerCase();
    if (value === 'ok' || value === 'true' || value === '1') {
      return 'ok';
    }
    if (
      value === 'nok' ||
      value === 'ko' ||
      value === 'false' ||
      value === '0'
    ) {
      return 'nok';
    }
    if (value === 'not_done' || value === 'not-done' || value === 'not done') {
      return 'nok';
    }
    if (value === 'na' || value === 'n/a' || value === 'not applicable') {
      return 'na';
    }
  }

  if (typeof raw === 'boolean') {
    return raw ? 'ok' : 'nok';
  }

  if (typeof raw === 'number') {
    return raw > 0 ? 'ok' : 'nok';
  }

  return 'nok';
}

/**
 * Normalizes a raw color value from the backend into a {@link TpmDetailColor}.
 * @param raw - Raw color value.
 * @returns Normalized color, or `undefined` when not recognized.
 */
function normalizeColor(raw: unknown): TpmDetailColor | undefined {
  if (typeof raw !== 'string') {
    return undefined;
  }

  const value = raw.trim().toLowerCase();
  if (
    value === 'green' ||
    value === 'red' ||
    value === 'yellow' ||
    value === 'gray' ||
    value === 'grey'
  ) {
    return value as TpmDetailColor;
  }

  return undefined;
}

/**
 * Derives a {@link TpmDetailStatus} from a recognized color.
 * @param color - Normalized color.
 * @returns Derived status or `undefined` when not derivable.
 */
function statusFromColor(
  color: TpmDetailColor | undefined,
): TpmDetailStatus | undefined {
  if (!color) {
    return undefined;
  }
  if (color === 'green') {
    return 'ok';
  }
  if (color === 'red') {
    return 'nok';
  }
  if (color === 'gray' || color === 'grey') {
    return 'na';
  }
  return undefined;
}

/**
 * Normalizes a raw backend record into a {@link TpmDetailItem}.
 * @param record - Raw backend object containing TPM detail fields.
 * @returns The normalized TPM detail item, or `undefined` when no valid `id` can be derived.
 */
function normalizeTpmDetailItem(
  record: Record<string, unknown>,
): TpmDetailItem | undefined {
  const idRaw = record.id ?? record.taskId ?? record.checkpointId;
  const id = typeof idRaw === 'number' ? idRaw : Number(idRaw);
  if (!Number.isFinite(id)) {
    return undefined;
  }

  const descriptionRaw =
    record.description ?? record.label ?? record.checkpointDescription;
  const description = typeof descriptionRaw === 'string' ? descriptionRaw : '';

  const statusRaw = record.status ?? record.result ?? record.value;
  const color = normalizeColor(record.color);
  const status =
    statusRaw === undefined
      ? (statusFromColor(color) ?? 'nok')
      : normalizeStatus(statusRaw);

  return {
    description,
    id,
    status,
    ...(color ? { color } : {}),
  };
}

/**
 * Normalizes a raw backend payload into a {@link TpmDetailsResponse}.
 * @param raw - Raw payload returned by the backend (expected to be an array of TPM detail records).
 * @returns A normalized TPM details response (empty array when the payload is not an array).
 */
function normalizeTpmDetailsResponse(raw: unknown): TpmDetailsResponse {
  if (!Array.isArray(raw)) {
    return [];
  }

  const normalized: Array<TpmDetailItem> = [];
  for (const item of raw) {
    if (item && typeof item === 'object') {
      const processed = normalizeTpmDetailItem(item as Record<string, unknown>);
      if (processed) {
        normalized.push(processed);
      }
    }
  }

  return normalized;
}

/**
 * Fetches TPM detail items for a given GAP and time range.
 * @param query - The TPM details query (GAP id, plant, time range, timezone).
 * @returns A promise that resolves to a normalized list of TPM detail items.
 */
export async function fetchTpmDetails(
  query: GetTpmDetailsQuery,
): Promise<TpmDetailsResponse> {
  const parameters = new URLSearchParams({
    gapId: query.gapId,
    plant: query.plant,
    shiftEndDate: query.shiftEndDate,
    shiftStartDate: query.shiftStartDate,
    timezone: query.timezone,
  });

  const url = `${edashboardBackendBaseUrl}/egap-board/tpm-details?${parameters.toString()}`;

  const headers = new Headers();
  headers.set('Content-Type', 'application/json');
  if (token) {
    headers.set('authorization', `Bearer ${token}`);
  }

  const response = await fetch(url, {
    credentials: 'include',
    headers,
    method: 'GET',
  });

  if (!response.ok) {
    throw new Error(`Failed to fetch tpm details: ${response.statusText}`);
  }

  let rawData: unknown;
  if (response.status !== 204) {
    try {
      rawData = await response.json();
    } catch {
      rawData = undefined;
    }
  }

  return normalizeTpmDetailsResponse(rawData);
}

