// âââ Page Layout Store (Composition API) âââââââââââââââââââââââââââââââââââââ
export const usePageLayoutStore = defineStore(
  'page-layout',
  () => {
    // âââ State âââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ
    /** Current active layout document (from API or mock) */
    const currentLayout = ref<PageLayoutDocument | undefined>(undefined);
    /** All available layouts for the current context */
    const availableLayouts = ref<Array<PageLayoutDocument>>([]);
    /** Loading state for API calls */
    const isLoading = ref(false);
    /** Error message from the last failed operation */
    const error = ref<string | undefined>(undefined);
    /** Whether data was successfully loaded from API (not mock) */
    const isApiDataLoaded = ref(false);
    /** Current device type for responsive layout selection */
    const currentDevice = ref<'desktop' | 'tablet' | 'mobile'>('desktop');
    /** Force static layout mode (ignores dynamic layout even if available) */
    const forceStaticLayout = ref(false);

    // âââ Getters âââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ
    /** Returns true if a valid layout is loaded (API or mock). */
    const hasLayout = computed(() => currentLayout.value !== undefined);

    /** Returns true if layout was loaded from API. */
    const isFromApi = computed(() => isApiDataLoaded.value);

    /** Returns true if currently loading layout from API. */
    const isLoadingLayout = computed(() => isLoading.value);

    /**
     * Returns the layout sections for the current device.
     * Falls back to desktop if the current device has no sections.
     */
    const layoutSections = computed<Array<SectionConfig>>(() => {
      if (!currentLayout.value?.devices) return [];

      const { devices } = currentLayout.value;
      const entry = devices[currentDevice.value];
      const sections = entry?.layout?.sections;

      // Fallback to desktop if the chosen device has no sections
      const resolved =
        sections && sections.length > 0
          ? sections
          : (devices.desktop?.layout?.sections ?? []);

      // Sort by order ascending
      return [...resolved].sort((a, b) => a.order - b.order);
    });

    /**
     * Returns true if using dynamic layout.
     * Dynamic layout is used when:
     * 1. forceStaticLayout is false (user hasn't toggled to static)
     * 2. A layout is loaded (from API OR mock data)
     * 3. The layout has valid sections
     *
     * Both API data and mock data are considered "dynamic" since you can
     * modify the order, add/remove widgets, etc. in the JSON config.
     */
    const useDynamicLayout = computed(() => {
      // User toggled to force static layout
      if (forceStaticLayout.value) return false;

      // Must have a layout loaded (API or mock)
      if (!currentLayout.value) return false;

      // Must have valid sections
      const sections = currentLayout.value?.devices?.desktop?.layout?.sections;
      return Array.isArray(sections) && sections.length > 0;
    });

    /** Returns the layout label/name. */
    const layoutLabel = computed(() => currentLayout.value?.label ?? '');

    /** Returns the layout status. */
    const layoutStatus = computed(() => currentLayout.value?.status ?? '');

    /** Returns the template ID. */
    const templateId = computed(() => currentLayout.value?.id ?? '');

    /** Returns the plant ID. */
    const plant = computed(() => currentLayout.value?.plant ?? undefined);

    /** Returns the scope list. */
    const scopeList = computed(() => currentLayout.value?.scopeList ?? []);

    /**
     * Returns true if a layout has at least one section.
     * @param layout - The layout document to check (optional)
     * @returns true if the layout has at least one section, false otherwise
     */
    function hasLayoutSections(layout?: PageLayoutDocument): boolean {
      const sections = layout?.devices?.desktop?.layout?.sections;
      return Array.isArray(sections) && sections.length > 0;
    }

    // /** Returns the layout width (in pixels) for the current device. */
    // Const layoutWidth = computed(() => {
    //   If (!currentLayout.value?.devices) return;
    //   Const { devices } = currentLayout.value;
    //   Const entry = devices[currentDevice.value];
    //   Return entry?.layout?.width ?? devices.desktop?.layout?.width;
    // });

    // /** Returns the layout height (in pixels) for the current device. */
    // Const layoutHeight = computed(() => {
    //   If (!currentLayout.value?.devices) return;
    //   Const { devices } = currentLayout.value;
    //   Const entry = devices[currentDevice.value];
    //   Return entry?.layout?.height ?? devices.desktop?.layout?.height;
    // });

    // âââ Actions âââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ
    /**
     * Detects the current device type based on window width.
     */
    function detectDevice(): void {
      const width = window.innerWidth;
      if (width < 768) {
        currentDevice.value = 'mobile';
      } else if (width < 1024) {
        currentDevice.value = 'tablet';
      } else {
        currentDevice.value = 'desktop';
      }
    }

    /**
     * Sets the current device type manually.
     * @param device - The device type to set ('desktop', 'tablet', or 'mobile')
     */
    function setDevice(device: 'desktop' | 'tablet' | 'mobile'): void {
      currentDevice.value = device;
    }

    /**
     * Toggles between static and dynamic layout modes.
     * @param useStatic - true to force static layout, false to allow dynamic
     */
    function setLayoutMode(useStatic: boolean): void {
      forceStaticLayout.value = useStatic;
      console.log(
        `[PageLayoutStore] Layout mode set to: ${useStatic ? 'STATIC' : 'DYNAMIC'}`,
      );
    }

    /**
     * Toggles layout mode (convenience method).
     */
    function toggleLayoutMode(): void {
      setLayoutMode(!forceStaticLayout.value);
    }

    /**
     * Forces static layout mode without loading any dynamic layout.
     * Use this as fallback when API fails and you don't want mock data.
     */
    function forceStaticLayoutMode(): void {
      currentLayout.value = undefined;
      isApiDataLoaded.value = false;
      forceStaticLayout.value = true;
      console.log(
        '[PageLayoutStore] Forced static layout mode (no dynamic layout)',
      );
    }

    /**
     * Initializes the store from the hierarchy store.
     * Determines scopeType/scopeValue from available hierarchy data.
     * Falls back to default layout when scope lookup returns empty, then static layout.
     */
    async function initializeFromHierarchy(): Promise<void> {
      detectDevice();
      isLoading.value = true;
      error.value = undefined;
      isApiDataLoaded.value = false;

      const hierarchyStore = useHierarchyStore();
      const plantId = hierarchyStore.plant
        ? Number(hierarchyStore.plant)
        : undefined;
      const resourceId = hierarchyStore.resource;
      const workcenterId = hierarchyStore.workcenter;

      // Determine scope type and value based on hierarchy
      let scopeType: string | undefined;
      let scopeValue: string | undefined;

      if (resourceId) {
        scopeType = 'Resource';
        scopeValue = resourceId;
      } else if (workcenterId) {
        scopeType = 'Workcenter';
        scopeValue = workcenterId;
      }

      if (!plantId || !scopeType || !scopeValue) {
        console.warn(
          '[PageLayoutStore] Missing plant, scopeType, or scopeValue - using static layout',
        );
        error.value = 'missing_scope';
        forceStaticLayoutMode();
        isLoading.value = false;
        return;
      }

      try {
        console.log(
          `[PageLayoutStore] Fetching layout by scope: plantId=${plantId}, scopeType=${scopeType}, scopeValue=${scopeValue}`,
        );
        const response = await pageLayoutApiService.getLayoutByScope(
          plantId,
          scopeType,
          scopeValue,
        );

        if (
          response.success &&
          response.data &&
          hasLayoutSections(response.data)
        ) {
          currentLayout.value = response.data;
          isApiDataLoaded.value = true;
          forceStaticLayout.value = false; // Enable dynamic layout
          console.log('[PageLayoutStore] Loaded layout from API by scope');
        } else {
          console.warn(
            '[PageLayoutStore] No layout found for scope - fetching default layout',
          );

          const defaultResponse = await pageLayoutApiService.getDefaultLayout();

          if (
            defaultResponse.success &&
            defaultResponse.data &&
            hasLayoutSections(defaultResponse.data)
          ) {
            currentLayout.value = defaultResponse.data;
            isApiDataLoaded.value = true;
            forceStaticLayout.value = false; // Enable dynamic layout
            console.log('[PageLayoutStore] Loaded default layout from API');
          } else {
            console.warn(
              '[PageLayoutStore] No default layout found - using static layout',
            );
            error.value =
              'Layout unavailable. No scope or default layout returned.';
            forceStaticLayoutMode();
          }
        }
      } catch (fetchError) {
        const message =
          fetchError instanceof Error ? fetchError.message : 'Unknown error';
        error.value = message;
        console.error(
          '[PageLayoutStore] Error fetching layout by scope:',
          message,
        );
        forceStaticLayoutMode();
      } finally {
        isLoading.value = false;
      }
    }

    // âââ Watchers ââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ
    /**
     * Watch for changes in the hierarchy store (plant, resource, workcenter).
     * When the user selects a new resource/workcenter, automatically fetch the layout for that scope.
     */
    const hierarchyStore = useHierarchyStore();
    watch(
      () => ({
        plant: hierarchyStore.plant,
        resource: hierarchyStore.resource,
        workcenter: hierarchyStore.workcenter,
      }),
      async () => {
        // Prevent refetching if already loading
        if (isLoading.value) {
          return;
        }

        await initializeFromHierarchy();
      },
      {
        immediate: false,
        deep: true,
      },
    );

    /**
     * Sets the current layout directly from API data.
     * Use this for manual override with API-fetched data.
     * @param layout - The layout document to set as current
     * @param fromApi - Whether this layout is from API (true) or mock/manual (false)
     */
    function setCurrentLayout(
      layout: PageLayoutDocument,
      fromApi = true,
    ): void {
      currentLayout.value = layout;
      isApiDataLoaded.value = fromApi;
      error.value = undefined;
    }

    /**
     * Clears the current layout (will trigger static fallback).
     */
    function clearLayout(): void {
      currentLayout.value = undefined;
      isApiDataLoaded.value = false;
      error.value = undefined;
    }

    /**
     * Resets the store to initial state.
     */
    function resetStore(): void {
      currentLayout.value = undefined;
      availableLayouts.value = [];
      isLoading.value = false;
      error.value = undefined;
      isApiDataLoaded.value = false;
      forceStaticLayout.value = false;
      currentDevice.value = 'desktop';
    }

    return {
      clearLayout,
      currentDevice,
      currentLayout,
      detectDevice,
      error,
      forceStaticLayout,
      forceStaticLayoutMode,
      hasLayout,
      initializeFromHierarchy,
      isApiDataLoaded,
      isFromApi,
      isLoading,
      isLoadingLayout,
      layoutLabel,
      layoutSections,
      layoutStatus,
      plant,
      resetStore,
      scopeList,
      setCurrentLayout,
      setDevice,
      setLayoutMode,
      templateId,
      toggleLayoutMode,
      useDynamicLayout,
    };
  },
  {
    persist: {
      // Persist device and layout mode preferences
      paths: ['currentDevice', 'forceStaticLayout'],
    },
  },
);

